"""Schema model: object types plus the @entity / @link mapping directives.

Mapping declaration problems (missing or conflicting entity/directive
declarations, dangling type references) raise PlanError "MappingError".
"""

from __future__ import annotations

from typing import Dict, List, Optional, Tuple

from .errors import PlanError
from .gql import Directive, TypeRef, parse_schema_document

BUILTIN_SCALARS = frozenset({"Int", "Float", "String", "Boolean", "ID"})


def named_of(type_ref: TypeRef) -> str:
    """Unwrap list/non-null wrappers down to the named type."""
    while type_ref[0] in ("list", "non_null"):
        type_ref = type_ref[1]
    return type_ref[1]


class Entity:
    __slots__ = ("type_name", "table", "key")

    def __init__(self, type_name: str, table: str, key: List[str]):
        self.type_name = type_name
        self.table = table
        self.key = key  # primary key field names, in declared order


class FieldInfo:
    __slots__ = ("name", "type_ref", "args", "link_directives", "link")

    def __init__(self, name, type_ref, args, link_directives):
        self.name = name
        self.type_ref = type_ref
        self.args = args  # Dict[str, InputValueDef]
        self.link_directives = link_directives
        # (local names, target names, declared_as_arrays) once validated
        self.link: Optional[Tuple[List[str], List[str], bool]] = None


class TypeInfo:
    __slots__ = ("name", "fields", "interfaces", "entity")

    def __init__(self, name: str, interfaces: List[str]):
        self.name = name
        self.fields: Dict[str, FieldInfo] = {}
        self.interfaces = interfaces
        self.entity: Optional[Entity] = None


class Schema:
    def __init__(self):
        self.types: Dict[str, TypeInfo] = {}
        self.scalars = set(BUILTIN_SCALARS)
        self.enums = set()
        self.inputs: Dict[str, Dict[str, object]] = {}
        self.interfaces = set()
        self.unions: Dict[str, List[str]] = {}
        self.roots: Dict[str, str] = {}  # "query" | "mutation" | "subscription" -> type name

    def is_leaf(self, type_name: str) -> bool:
        return type_name in self.scalars or type_name in self.enums

    def known_type(self, type_name: str) -> bool:
        return (
            type_name in self.scalars
            or type_name in self.enums
            or type_name in self.types
            or type_name in self.inputs
            or type_name in self.interfaces
            or type_name in self.unions
        )


def _mapping_error(message: str) -> PlanError:
    return PlanError("MappingError", message)


def load_schema(text: str, source: str = "<schema>") -> Schema:
    doc = parse_schema_document(text, source)
    schema = Schema()
    schema.scalars |= set(doc.scalars)
    schema.enums = set(doc.enums)
    schema.interfaces = {tdef.name for tdef in doc.interfaces}
    schema.unions = dict(doc.unions)

    for input_def in doc.inputs:
        if input_def.name in schema.inputs:
            raise _mapping_error(f"duplicate input type '{input_def.name}'")
        fields: Dict[str, object] = {}
        for fdef in input_def.fields:
            if fdef.name in fields:
                raise _mapping_error(
                    f"duplicate field '{fdef.name}' on input '{input_def.name}'"
                )
            fields[fdef.name] = fdef
        schema.inputs[input_def.name] = fields

    # Merge plain definitions with `extend type` blocks.
    slots: Dict[str, dict] = {}
    for tdef in doc.types:
        slot = slots.setdefault(
            tdef.name, {"fields": [], "directives": [], "interfaces": [], "defined": False}
        )
        if not tdef.is_extend:
            if slot["defined"]:
                raise _mapping_error(f"duplicate definition of type '{tdef.name}'")
            slot["defined"] = True
        slot["fields"].extend(tdef.fields)
        slot["directives"].extend(tdef.directives)
        for iface in tdef.interfaces:
            if iface not in slot["interfaces"]:
                slot["interfaces"].append(iface)

    reserved = set(schema.scalars) | schema.enums | set(schema.inputs) | schema.interfaces | set(schema.unions)
    for name in slots:
        if name in reserved:
            raise _mapping_error(f"name '{name}' is defined more than once")

    for name, slot in slots.items():
        info = TypeInfo(name, slot["interfaces"])
        for iface in slot["interfaces"]:
            if iface not in schema.interfaces:
                raise _mapping_error(f"type '{name}' implements unknown interface '{iface}'")
        for fdef in slot["fields"]:
            if fdef.name in info.fields:
                raise _mapping_error(f"duplicate field '{fdef.name}' on type '{name}'")
            args: Dict[str, object] = {}
            for adef in fdef.args:
                if adef.name in args:
                    raise _mapping_error(
                        f"duplicate argument '{adef.name}' on '{name}.{fdef.name}'"
                    )
                args[adef.name] = adef
            link_directives = [d for d in fdef.directives if d.name == "link"]
            info.fields[fdef.name] = FieldInfo(fdef.name, fdef.type, args, link_directives)
        entity_directives = [d for d in slot["directives"] if d.name == "entity"]
        if len(entity_directives) > 1:
            raise _mapping_error(f"type '{name}' has multiple @entity directives")
        if entity_directives:
            info.entity = _build_entity(schema, info, entity_directives[0])
        schema.types[name] = info

    _validate_type_references(schema)
    _validate_links(schema)
    _validate_entity_tables(schema)
    _resolve_roots(schema, doc.roots)
    return schema


def _normalize_field_list(value, what: str) -> Tuple[List[str], bool]:
    """Normalize a string-or-string-array directive argument.

    Returns (field names in declared order, declared_as_array). Anything
    else (empty arrays, non-string elements, duplicates, other types) is a
    MappingError.
    """
    if isinstance(value, str):
        if not value:
            raise _mapping_error(f"{what} requires a non-empty string")
        return [value], False
    if isinstance(value, list):
        if not value:
            raise _mapping_error(f"{what} must not be an empty array")
        names: List[str] = []
        for item in value:
            if not isinstance(item, str) or not item:
                raise _mapping_error(f"{what} must contain only non-empty strings")
            if item in names:
                raise _mapping_error(f"{what} contains duplicate field '{item}'")
            names.append(item)
        return names, True
    raise _mapping_error(f"{what} must be a string or an array of strings")


def _build_entity(schema: Schema, info: TypeInfo, directive: Directive) -> Entity:
    table = directive.args.get("name")
    if not isinstance(table, str) or not table:
        raise _mapping_error(f"@entity on '{info.name}' requires a non-empty string 'name'")
    key, _ = _normalize_field_list(
        directive.args.get("key"), f"@entity 'key' of type '{info.name}'"
    )
    for name in key:
        key_field = info.fields.get(name)
        if key_field is None:
            raise _mapping_error(f"@entity key '{name}' is not a field of type '{info.name}'")
        if named_of(key_field.type_ref) not in schema.scalars:
            raise _mapping_error(f"@entity key '{name}' of type '{info.name}' must be a scalar")
    return Entity(info.name, table, key)


def _validate_type_references(schema: Schema) -> None:
    def check(type_ref: TypeRef, where: str) -> None:
        name = named_of(type_ref)
        if not schema.known_type(name):
            raise _mapping_error(f"unknown type '{name}' referenced by {where}")

    for info in schema.types.values():
        for field in info.fields.values():
            check(field.type_ref, f"'{info.name}.{field.name}'")
            for arg in field.args.values():
                check(arg.type, f"argument '{arg.name}' of '{info.name}.{field.name}'")
    for input_name, fields in schema.inputs.items():
        for fdef in fields.values():
            check(fdef.type, f"input field '{input_name}.{fdef.name}'")
    for union_name, members in schema.unions.items():
        for member in members:
            if member not in schema.types:
                raise _mapping_error(f"union '{union_name}' references unknown type '{member}'")


def _validate_links(schema: Schema) -> None:
    for info in schema.types.values():
        for field in info.fields.values():
            directives = field.link_directives
            if len(directives) > 1:
                raise _mapping_error(f"field '{info.name}.{field.name}' has multiple @link directives")
            if not directives:
                continue
            directive = directives[0]
            where = f"@link on '{info.name}.{field.name}'"
            local, local_is_array = _normalize_field_list(
                directive.args.get("local"), f"{where} argument 'local'"
            )
            target, target_is_array = _normalize_field_list(
                directive.args.get("target"), f"{where} argument 'target'"
            )
            if local_is_array != target_is_array:
                raise _mapping_error(
                    f"{where} must use the same form (string or array) for 'local' and 'target'"
                )
            if len(local) != len(target):
                raise _mapping_error(
                    f"{where} has {len(local)} local field(s) but {len(target)} target field(s)"
                )
            target_type = named_of(field.type_ref)
            target_info = schema.types.get(target_type)
            if target_info is None:
                raise _mapping_error(
                    f"@link on '{info.name}.{field.name}' must point to an object type"
                )
            for name in local:
                local_field = info.fields.get(name)
                if local_field is None:
                    raise _mapping_error(
                        f"@link local field '{name}' is not a field of type '{info.name}'"
                    )
                if named_of(local_field.type_ref) not in schema.scalars:
                    raise _mapping_error(
                        f"@link local field '{name}' of type '{info.name}' must be a scalar"
                    )
            for name in target:
                if name not in target_info.fields:
                    raise _mapping_error(
                        f"@link target field '{name}' is not a field of type '{target_type}'"
                    )
            field.link = (local, target, local_is_array)


def _validate_entity_tables(schema: Schema) -> None:
    tables: Dict[str, str] = {}
    for info in schema.types.values():
        if info.entity is None:
            continue
        other = tables.get(info.entity.table)
        if other is not None:
            raise _mapping_error(
                f"entity '{info.entity.table}' is mapped by both '{other}' and '{info.name}'"
            )
        tables[info.entity.table] = info.name


def _resolve_roots(schema: Schema, declared: Dict[str, str]) -> None:
    for op, default_name in (("query", "Query"), ("mutation", "Mutation"), ("subscription", "Subscription")):
        if default_name in schema.types:
            schema.roots[op] = default_name
    for op, type_name in declared.items():
        if type_name not in schema.types:
            raise _mapping_error(f"root type '{type_name}' for {op} is not defined")
        schema.roots[op] = type_name

"""Self-contained GraphQL lexer and parser.

Parses both schema definition documents (SDL) and executable documents
(operations, fragments) into small dataclass ASTs. Syntax problems raise
PlanError with code "ParseError".
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

from .errors import PlanError

PUNCTUATORS = set("!$():=@[]{|}&")
NUMBER_RE = re.compile(r"-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?")

# Type references are nested tuples: ("named", name) | ("list", ref) | ("non_null", ref).
TypeRef = Tuple


# ---------------------------------------------------------------------------
# AST nodes
# ---------------------------------------------------------------------------


@dataclass
class Var:
    name: str


@dataclass
class Directive:
    name: str
    args: Dict[str, Any]


@dataclass
class InputValueDef:
    name: str
    type: TypeRef
    default: Any = None
    has_default: bool = False


@dataclass
class FieldDef:
    name: str
    args: List[InputValueDef]
    type: TypeRef
    directives: List[Directive]


@dataclass
class ObjectTypeDef:
    name: str
    fields: List[FieldDef]
    directives: List[Directive]
    interfaces: List[str]
    is_extend: bool = False


@dataclass
class InputDef:
    name: str
    fields: List[InputValueDef]


@dataclass
class Operation:
    op_type: str  # "query" | "mutation" | "subscription"
    name: Optional[str]
    var_defs: List[Tuple[str, TypeRef, Any, bool]]  # (name, type, default, has_default)
    selection_set: list


@dataclass
class FieldNode:
    name: str
    alias: Optional[str]
    args: Dict[str, Any]
    selection_set: Optional[list]  # None when the field has no subselection


@dataclass
class FragmentSpread:
    name: str


@dataclass
class InlineFragment:
    type_condition: Optional[str]
    selection_set: list


@dataclass
class FragmentDef:
    name: str
    type_condition: str
    selection_set: list


@dataclass
class Token:
    kind: str  # "name" | "int" | "float" | "string" | "punct" | "eof"
    value: str
    line: int
    col: int


# ---------------------------------------------------------------------------
# Lexer
# ---------------------------------------------------------------------------


def tokenize(text: str, source: str) -> List[Token]:
    tokens: List[Token] = []
    i = 0
    line = 1
    col = 1
    n = len(text)

    def error(message: str, ln: Optional[int] = None, cl: Optional[int] = None):
        raise PlanError("ParseError", f"{source}:{ln or line}:{cl or col}: {message}")

    while i < n:
        ch = text[i]
        if ch in " \t\r\n,":
            if ch == "\n":
                line += 1
                col = 1
            else:
                col += 1
            i += 1
            continue
        if ch == "#":
            while i < n and text[i] != "\n":
                i += 1
                col += 1
            continue
        start_line, start_col = line, col
        if ch == ".":
            if text[i : i + 3] == "...":
                tokens.append(Token("punct", "...", start_line, start_col))
                i += 3
                col += 3
                continue
            error("unexpected character '.'")
        if ch in PUNCTUATORS:
            tokens.append(Token("punct", ch, start_line, start_col))
            i += 1
            col += 1
            continue
        if ch == '"':
            if text[i : i + 3] == '"""':
                j = i + 3
                buf: List[str] = []
                closed = False
                while j < n:
                    if text[j] == "\\" and text[j + 1 : j + 4] == '"""':
                        buf.append('"""')
                        j += 4
                    elif text[j : j + 3] == '"""':
                        closed = True
                        break
                    else:
                        buf.append(text[j])
                        j += 1
                if not closed:
                    error("unterminated block string", start_line, start_col)
                segment = text[i : j + 3]
                tokens.append(Token("string", "".join(buf), start_line, start_col))
                i = j + 3
            else:
                j = i + 1
                buf = []
                closed = False
                while j < n:
                    c = text[j]
                    if c == '"':
                        closed = True
                        break
                    if c == "\n":
                        error("unterminated string", start_line, start_col)
                    if c == "\\":
                        esc = text[j + 1] if j + 1 < n else ""
                        simple = {
                            '"': '"',
                            "\\": "\\",
                            "/": "/",
                            "b": "\b",
                            "f": "\f",
                            "n": "\n",
                            "r": "\r",
                            "t": "\t",
                        }
                        if esc == "u":
                            hexs = text[j + 2 : j + 6]
                            if len(hexs) < 4 or any(
                                c2 not in "0123456789abcdefABCDEF" for c2 in hexs
                            ):
                                error("invalid unicode escape", start_line, start_col)
                            buf.append(chr(int(hexs, 16)))
                            j += 6
                        elif esc in simple:
                            buf.append(simple[esc])
                            j += 2
                        else:
                            error(f"invalid escape '\\{esc}'", start_line, start_col)
                    else:
                        buf.append(c)
                        j += 1
                if not closed:
                    error("unterminated string", start_line, start_col)
                segment = text[i : j + 1]
                tokens.append(Token("string", "".join(buf), start_line, start_col))
                i = j + 1
            newlines = segment.count("\n")
            if newlines:
                line += newlines
                col = len(segment) - segment.rindex("\n")
            else:
                col += len(segment)
            continue
        if ch == "-" or ch.isdigit():
            m = NUMBER_RE.match(text, i)
            if not m:
                error("invalid number", start_line, start_col)
            sval = m.group(0)
            kind = "float" if ("." in sval or "e" in sval or "E" in sval) else "int"
            tokens.append(Token(kind, sval, start_line, start_col))
            i = m.end()
            col += len(sval)
            continue
        if ch.isalpha() or ch == "_":
            j = i
            while j < n and (text[j].isalnum() or text[j] == "_"):
                j += 1
            tokens.append(Token("name", text[i:j], start_line, start_col))
            col += j - i
            i = j
            continue
        error(f"unexpected character {ch!r}")
    tokens.append(Token("eof", "", line, col))
    return tokens


# ---------------------------------------------------------------------------
# Parser
# ---------------------------------------------------------------------------


class Parser:
    def __init__(self, text: str, source: str):
        self.source = source
        self.tokens = tokenize(text, source)
        self.pos = 0

    def peek(self) -> Token:
        return self.tokens[self.pos]

    def error(self, message: str) -> "PlanError":
        tok = self.peek()
        raise PlanError("ParseError", f"{self.source}:{tok.line}:{tok.col}: {message}")

    def describe(self) -> str:
        tok = self.peek()
        if tok.kind == "eof":
            return "end of input"
        return repr(tok.value)

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        if tok.kind != "eof":
            self.pos += 1
        return tok

    def at_punct(self, p: str) -> bool:
        tok = self.peek()
        return tok.kind == "punct" and tok.value == p

    def eat_punct(self, p: str) -> bool:
        if self.at_punct(p):
            self.advance()
            return True
        return False

    def expect_punct(self, p: str) -> None:
        if not self.eat_punct(p):
            self.error(f"expected '{p}', found {self.describe()}")

    def at_name(self, name: Optional[str] = None) -> bool:
        tok = self.peek()
        return tok.kind == "name" and (name is None or tok.value == name)

    def expect_name(self) -> str:
        tok = self.peek()
        if tok.kind != "name":
            self.error(f"expected a name, found {self.describe()}")
        self.advance()
        return tok.value

    # -- types ---------------------------------------------------------------

    def parse_type_ref(self) -> TypeRef:
        if self.eat_punct("["):
            inner = self.parse_type_ref()
            self.expect_punct("]")
            ref: TypeRef = ("list", inner)
        else:
            ref = ("named", self.expect_name())
        if self.eat_punct("!"):
            ref = ("non_null", ref)
        return ref

    # -- values ----------------------------------------------------------------

    def parse_value(self, const: bool = False) -> Any:
        tok = self.peek()
        if tok.kind == "punct" and tok.value == "$":
            if const:
                self.error("variables are not allowed in this position")
            self.advance()
            return Var(self.expect_name())
        if tok.kind == "int":
            self.advance()
            return int(tok.value)
        if tok.kind == "float":
            self.advance()
            return float(tok.value)
        if tok.kind == "string":
            self.advance()
            return tok.value
        if tok.kind == "name":
            self.advance()
            if tok.value == "true":
                return True
            if tok.value == "false":
                return False
            if tok.value == "null":
                return None
            return tok.value  # enum value
        if self.eat_punct("["):
            items = []
            while not self.eat_punct("]"):
                items.append(self.parse_value(const))
            return items
        if self.eat_punct("{"):
            obj: Dict[str, Any] = {}
            while not self.eat_punct("}"):
                key = self.expect_name()
                if key in obj:
                    self.error(f"duplicate object field '{key}'")
                self.expect_punct(":")
                obj[key] = self.parse_value(const)
            return obj
        self.error(f"expected a value, found {self.describe()}")

    def parse_directives(self, const: bool = False) -> List[Directive]:
        directives = []
        while self.eat_punct("@"):
            name = self.expect_name()
            args: Dict[str, Any] = {}
            if self.eat_punct("("):
                while not self.eat_punct(")"):
                    arg_name = self.expect_name()
                    if arg_name in args:
                        self.error(f"duplicate argument '{arg_name}' on '@{name}'")
                    self.expect_punct(":")
                    args[arg_name] = self.parse_value(const)
            directives.append(Directive(name, args))
        return directives

    # -- executable documents ---------------------------------------------------

    def parse_selection_set(self) -> list:
        self.expect_punct("{")
        selections = []
        while not self.at_punct("}"):
            if self.peek().kind == "eof":
                self.error("unterminated selection set")
            selections.append(self.parse_selection())
        self.expect_punct("}")
        return selections

    def parse_selection(self):
        if self.eat_punct("..."):
            if self.at_name("on"):
                self.advance()
                condition = self.expect_name()
                self.parse_directives()
                return InlineFragment(condition, self.parse_selection_set())
            if self.at_punct("{") or self.at_punct("@"):
                self.parse_directives()
                return InlineFragment(None, self.parse_selection_set())
            name = self.expect_name()
            self.parse_directives()
            return FragmentSpread(name)
        first = self.expect_name()
        alias = None
        name = first
        if self.eat_punct(":"):
            alias = first
            name = self.expect_name()
        args: Dict[str, Any] = {}
        if self.eat_punct("("):
            while not self.eat_punct(")"):
                arg_name = self.expect_name()
                if arg_name in args:
                    self.error(f"duplicate argument '{arg_name}'")
                self.expect_punct(":")
                args[arg_name] = self.parse_value()
        self.parse_directives()
        selection_set = None
        if self.at_punct("{"):
            selection_set = self.parse_selection_set()
        return FieldNode(name, alias, args, selection_set)


def parse_executable(text: str, source: str):
    """Parse an executable document. Returns (operations, fragments)."""
    parser = Parser(text, source)
    operations: List[Operation] = []
    fragments: Dict[str, FragmentDef] = {}
    while parser.peek().kind != "eof":
        if parser.at_punct("{"):
            operations.append(Operation("query", None, [], parser.parse_selection_set()))
            continue
        if parser.at_name("query") or parser.at_name("mutation") or parser.at_name("subscription"):
            op_type = parser.advance().value
            name = None
            if parser.peek().kind == "name":
                name = parser.advance().value
            var_defs = []
            if parser.eat_punct("("):
                while not parser.eat_punct(")"):
                    parser.expect_punct("$")
                    var_name = parser.expect_name()
                    parser.expect_punct(":")
                    var_type = parser.parse_type_ref()
                    default = None
                    has_default = False
                    if parser.eat_punct("="):
                        default = parser.parse_value(const=True)
                        has_default = True
                    parser.parse_directives(const=True)
                    var_defs.append((var_name, var_type, default, has_default))
            parser.parse_directives()
            operations.append(Operation(op_type, name, var_defs, parser.parse_selection_set()))
            continue
        if parser.at_name("fragment"):
            parser.advance()
            frag_name = parser.expect_name()
            if frag_name == "on":
                parser.error("fragment name cannot be 'on'")
            if not parser.at_name("on"):
                parser.error("expected 'on' after fragment name")
            parser.advance()
            condition = parser.expect_name()
            parser.parse_directives()
            selection_set = parser.parse_selection_set()
            if frag_name in fragments:
                parser.error(f"duplicate fragment '{frag_name}'")
            fragments[frag_name] = FragmentDef(frag_name, condition, selection_set)
            continue
        parser.error(f"unexpected {parser.describe()}")
    return operations, fragments


# ---------------------------------------------------------------------------
# Schema (SDL) documents
# ---------------------------------------------------------------------------


class SdlDocument:
    def __init__(self):
        self.types: List[ObjectTypeDef] = []
        self.interfaces: List[ObjectTypeDef] = []
        self.inputs: List[InputDef] = []
        self.scalars: List[str] = []
        self.enums: List[str] = []
        self.unions: Dict[str, List[str]] = {}
        self.roots: Dict[str, str] = {}
        self.schema_seen = False


def _parse_field_def(parser: Parser) -> FieldDef:
    name = parser.expect_name()
    args: List[InputValueDef] = []
    if parser.eat_punct("("):
        while not parser.eat_punct(")"):
            if parser.peek().kind == "string":
                parser.advance()  # argument description
            args.append(_parse_input_value_def(parser))
    parser.expect_punct(":")
    type_ref = parser.parse_type_ref()
    directives = parser.parse_directives(const=True)
    return FieldDef(name, args, type_ref, directives)


def _parse_input_value_def(parser: Parser) -> InputValueDef:
    name = parser.expect_name()
    parser.expect_punct(":")
    type_ref = parser.parse_type_ref()
    default = None
    has_default = False
    if parser.eat_punct("="):
        default = parser.parse_value(const=True)
        has_default = True
    parser.parse_directives(const=True)
    return InputValueDef(name, type_ref, default, has_default)


def _parse_object_type(parser: Parser, is_extend: bool) -> ObjectTypeDef:
    name = parser.expect_name()
    interfaces: List[str] = []
    if parser.at_name("implements"):
        parser.advance()
        parser.eat_punct("&")
        interfaces.append(parser.expect_name())
        while parser.eat_punct("&"):
            interfaces.append(parser.expect_name())
    directives = parser.parse_directives(const=True)
    fields: List[FieldDef] = []
    if parser.eat_punct("{"):
        while not parser.eat_punct("}"):
            if parser.peek().kind == "string":
                parser.advance()  # field description
            fields.append(_parse_field_def(parser))
    return ObjectTypeDef(name, fields, directives, interfaces, is_extend)


def _parse_schema_body(parser: Parser, doc: SdlDocument) -> None:
    parser.parse_directives(const=True)
    parser.expect_punct("{")
    while not parser.eat_punct("}"):
        op = parser.expect_name()
        if op not in ("query", "mutation", "subscription"):
            parser.error(f"unknown root operation '{op}'")
        parser.expect_punct(":")
        type_name = parser.expect_name()
        if op in doc.roots:
            parser.error(f"duplicate root operation '{op}'")
        doc.roots[op] = type_name


def parse_schema_document(text: str, source: str) -> SdlDocument:
    parser = Parser(text, source)
    doc = SdlDocument()
    while parser.peek().kind != "eof":
        if parser.peek().kind == "string":
            parser.advance()  # definition description
        if parser.at_name("schema"):
            if doc.schema_seen:
                parser.error("duplicate schema definition")
            doc.schema_seen = True
            parser.advance()
            _parse_schema_body(parser, doc)
        elif parser.at_name("scalar"):
            parser.advance()
            doc.scalars.append(parser.expect_name())
            parser.parse_directives(const=True)
        elif parser.at_name("type"):
            parser.advance()
            doc.types.append(_parse_object_type(parser, is_extend=False))
        elif parser.at_name("interface"):
            parser.advance()
            doc.interfaces.append(_parse_object_type(parser, is_extend=False))
        elif parser.at_name("input"):
            parser.advance()
            name = parser.expect_name()
            parser.parse_directives(const=True)
            fields: List[InputValueDef] = []
            if parser.eat_punct("{"):
                while not parser.eat_punct("}"):
                    if parser.peek().kind == "string":
                        parser.advance()
                    fields.append(_parse_input_value_def(parser))
            doc.inputs.append(InputDef(name, fields))
        elif parser.at_name("enum"):
            parser.advance()
            doc.enums.append(parser.expect_name())
            parser.parse_directives(const=True)
            if parser.eat_punct("{"):
                while not parser.eat_punct("}"):
                    if parser.peek().kind == "string":
                        parser.advance()
                    parser.expect_name()
                    parser.parse_directives(const=True)
        elif parser.at_name("union"):
            parser.advance()
            union_name = parser.expect_name()
            parser.parse_directives(const=True)
            members: List[str] = []
            if parser.eat_punct("="):
                parser.eat_punct("|")
                members.append(parser.expect_name())
                while parser.eat_punct("|"):
                    members.append(parser.expect_name())
            doc.unions[union_name] = members
        elif parser.at_name("directive"):
            parser.advance()
            parser.expect_punct("@")
            parser.expect_name()
            if parser.eat_punct("("):
                while not parser.eat_punct(")"):
                    _parse_input_value_def(parser)
            if parser.at_name("repeatable"):
                parser.advance()
            if not parser.at_name("on"):
                parser.error("expected 'on' in directive definition")
            parser.advance()
            parser.eat_punct("|")
            parser.expect_name()
            while parser.eat_punct("|"):
                parser.expect_name()
        elif parser.at_name("extend"):
            parser.advance()
            if parser.at_name("type"):
                parser.advance()
                doc.types.append(_parse_object_type(parser, is_extend=True))
            elif parser.at_name("schema"):
                parser.advance()
                _parse_schema_body(parser, doc)
            else:
                parser.error("unsupported 'extend' target")
        else:
            parser.error(f"unexpected {parser.describe()}")
    return doc

"""Direct GraphQL query execution over entity change events.

Compiles a query operation into per-root filters and selection trees (sharing
the planner's fragment, variable and @link semantics), folds an NDJSON entity
change stream into the current primary-key snapshot of every reachable
entity, then answers the query once against those snapshots.

List roots return every matching row in first-insert order (UPDATE replaces a
row in place; DELETE followed by re-INSERT moves it to the end); single-object
roots return null on no match and fail with QueryError on more than one match.
Single-object @link fields follow local -> target primary key; list @link
fields equality-match arbitrary scalar target fields in target insert order.
"""

from __future__ import annotations

import json
from typing import Any, Dict, List, Optional, Tuple

from .errors import PlanError
from .gql import Var, parse_executable
from .planner import Planner
from .schema import Entity, Schema, TypeInfo, named_of
from .subscription import EVENT_OPS, _OrderedStore, _is_list_type

_MISSING = object()


class ExecNode:
    """A compiled field in the query selection tree.

    Leaf fields carry ``field_type`` and no children. Link fields also carry
    the validated @link mapping (local/target field names, target entity) and
    their compiled children; ``is_list`` selects list resolution.
    """

    __slots__ = (
        "response_key",
        "field_name",
        "field_type",
        "required",
        "is_list",
        "local",
        "local_types",
        "target",
        "target_types",
        "target_table",
        "children",
    )

    def __init__(
        self,
        response_key: str,
        field_name: str,
        field_type=None,
        required: bool = False,
        is_list: bool = False,
        local: Optional[List[str]] = None,
        local_types: Optional[List[Any]] = None,
        target: Optional[List[str]] = None,
        target_types: Optional[List[Any]] = None,
        target_table: Optional[str] = None,
        children: Optional[List["ExecNode"]] = None,
    ):
        self.response_key = response_key
        self.field_name = field_name
        self.field_type = field_type
        self.required = required
        self.is_list = is_list
        self.local = local
        self.local_types = local_types
        self.target = target
        self.target_types = target_types
        self.target_table = target_table
        self.children = children


class ExecContext:
    """Everything execution needs beyond the compiled roots."""

    __slots__ = ("schema", "entity_keys", "key_types", "snapshots")

    def __init__(self, schema: Schema, entity_keys: Dict[str, List[str]],
                 key_types: Dict[str, List[Any]]):
        self.schema = schema
        self.entity_keys = entity_keys
        # table -> primary key field type refs, in declared order
        self.key_types = key_types
        self.snapshots: Dict[str, _OrderedStore] = {}


class QueryCompiler(Planner):
    """Compiles a query document into one executable entry per root field."""

    def __init__(self, schema: Schema, variables: Dict[str, Any],
                 bound_args_allowed: bool = False):
        super().__init__(schema, variables, bound_args_allowed)
        self.entity_keys: Dict[str, List[str]] = {}
        self.key_types: Dict[str, List[Any]] = {}

    def compile(
        self, query_text: str, source: str, operation_name: Optional[str]
    ) -> Tuple[Optional[str], List[dict]]:
        operations, self.fragments = parse_executable(query_text, source)
        op = self._select_operation(operations, operation_name)
        if op.op_type != "query":
            raise PlanError(
                "UnsupportedOperation",
                f"{op.op_type} operations are not supported by query-exec",
            )
        self.var_map = {}
        for name, type_ref, default, has_default in op.var_defs:
            if name in self.var_map:
                raise PlanError(
                    "VariablesError", f"variable '${name}' is declared more than once"
                )
            self.var_map[name] = (type_ref, default, has_default)

        root_type_name = self.schema.roots.get("query")
        root_type = self.schema.types.get(root_type_name) if root_type_name else None
        if root_type is None:
            raise PlanError(
                "MappingError",
                "schema does not define a root type for query operations",
            )

        selections = self._expand(op.selection_set, root_type.name, [])
        if not selections:
            raise PlanError("InvalidQuery", "query has an empty selection set")

        roots: List[dict] = []
        self.entity_keys = {}
        self.key_types = {}
        for node in selections:
            # Introspection root fields cost 0 and are only recognized while
            # complexity control is enabled; the engine models no introspection
            # data, so such a root resolves deterministically to null.
            if self.bound_args_allowed and node.name in ("__schema", "__type"):
                roots.append({"introspection": node.alias or node.name})
                continue
            roots.append(self._compile_root(node, root_type))
        return op.name, roots

    # -- operation selection ---------------------------------------------------

    @staticmethod
    def _select_operation(operations, operation_name):
        if operation_name is not None:
            for op in operations:
                if op.name == operation_name:
                    return op
            raise PlanError("InvalidOperation", f"no operation named '{operation_name}'")
        if not operations:
            raise PlanError("InvalidRequest", "document contains no operations")
        if len(operations) == 1:
            return operations[0]
        raise PlanError(
            "InvalidRequest",
            "multiple operations found; select one with --operation",
        )

    # -- roots ------------------------------------------------------------------

    def _compile_root(self, node, root_type: TypeInfo) -> dict:
        key = node.alias or node.name
        field = root_type.fields.get(node.name)
        if field is None:
            raise PlanError(
                "UnknownField",
                f"unknown root field '{node.name}' on type '{root_type.name}'",
            )
        type_name = named_of(field.type_ref)
        target = self.schema.types.get(type_name)
        entity = target.entity if target is not None else None
        if entity is None:
            raise PlanError(
                "UnknownEntity",
                f"root field '{node.name}' does not return a mapped entity type",
            )
        if node.selection_set is None:
            raise PlanError(
                "InvalidQuery", f"root field '{node.name}' requires a selection set"
            )
        for arg_name, arg_def in field.args.items():
            if (
                arg_def.type[0] == "non_null"
                and not arg_def.has_default
                and arg_name not in node.args
            ):
                raise PlanError(
                    "UnknownField",
                    f"missing required argument '{arg_name}' on root field '{node.name}'",
                )
        is_list = _is_list_type(field.type_ref)
        filter_obj: Dict[str, Any] = {}
        filter_types: Dict[str, Any] = {}
        for arg_name, value in node.args.items():
            if self._accepts_bound_arg(is_list, arg_name):
                # A list-size bound used for complexity; never a filter. If it
                # is a variable, resolve it so type/required-variable errors
                # are reported by the normal validation phase.
                if isinstance(value, Var):
                    self._resolve(value)
                continue
            if arg_name not in field.args:
                raise PlanError(
                    "UnknownField",
                    f"unknown argument '{arg_name}' on root field '{node.name}'",
                )
            target_field = target.fields.get(arg_name)
            if target_field is None or not self.schema.is_leaf(
                named_of(target_field.type_ref)
            ):
                raise PlanError(
                    "UnknownField",
                    f"argument '{arg_name}' does not match a filterable field of "
                    f"entity '{entity.table}'",
                )
            filter_obj[arg_name] = self._resolve(value)
            filter_types[arg_name] = target_field.type_ref

        self.entity_keys[entity.table] = list(entity.key)
        self.key_types[entity.table] = [
            target.fields[name].type_ref for name in entity.key
        ]
        children = self._compile_fields(
            target, entity, node.selection_set, key
        )
        return {
            "response_key": key,
            "field_name": node.name,
            "table": entity.table,
            "filter": filter_obj,
            "filter_types": filter_types,
            "is_list": is_list,
            "children": children,
        }

    # -- selection tree -----------------------------------------------------------

    def _compile_fields(
        self,
        info: TypeInfo,
        entity: Entity,
        selection_set,
        path: str,
    ) -> List[ExecNode]:
        selections = self._expand(selection_set, info.name, [])
        if not selections:
            raise PlanError("InvalidQuery", f"empty selection set at '{path}'")
        children: List[ExecNode] = []
        seen = set()
        for node in selections:
            key = node.alias or node.name
            node_path = f"{path}.{key}"
            field = info.fields.get(node.name)
            if field is None:
                raise PlanError(
                    "UnknownField", f"unknown field '{node.name}' on type '{info.name}'"
                )
            type_name = named_of(field.type_ref)
            if self.schema.is_leaf(type_name):
                if node.selection_set is not None:
                    raise PlanError(
                        "InvalidQuery",
                        f"scalar field '{node.name}' must not have a selection set",
                    )
                if node.args:
                    raise PlanError(
                        "InvalidQuery",
                        f"arguments on field '{node.name}' are not supported",
                    )
                if key not in seen:
                    seen.add(key)
                    children.append(ExecNode(key, node.name, field.type_ref))
                continue
            is_list = _is_list_type(field.type_ref)
            for arg_name, value in node.args.items():
                if self._accepts_bound_arg(is_list, arg_name):
                    if isinstance(value, Var):
                        self._resolve(value)
                    continue
                raise PlanError(
                    "InvalidQuery",
                    f"arguments on field '{node.name}' are not supported",
                )
            if node.selection_set is None:
                raise PlanError(
                    "InvalidQuery", f"field '{node.name}' requires a selection set"
                )
            required = field.type_ref[0] == "non_null"
            if field.link is None:
                raise PlanError(
                    "MappingError",
                    f"field '{info.name}.{node.name}' is missing an @link directive",
                )
            target_info = self.schema.types.get(type_name)
            if target_info is None:
                raise PlanError(
                    "MappingError",
                    f"field '{info.name}.{node.name}' has unsupported type '{type_name}'",
                )
            target_entity = target_info.entity
            if target_entity is None:
                raise PlanError(
                    "UnknownEntity",
                    f"type '{target_info.name}' is not mapped to an entity",
                )
            local, target_fields, _as_array = field.link
            if is_list:
                for name in local:
                    if not _is_scalar_value_field(self.schema, info.fields.get(name)):
                        raise PlanError(
                            "MappingError",
                            f"@link local field '{name}' of type '{info.name}' "
                            f"must be a scalar",
                        )
                for name in target_fields:
                    matched = target_info.fields.get(name)
                    if matched is None:
                        raise PlanError(
                            "MappingError",
                            f"@link target field '{name}' is not a field of type "
                            f"'{target_info.name}'",
                        )
                    if not _is_scalar_value_field(self.schema, matched):
                        raise PlanError(
                            "MappingError",
                            f"@link target field '{name}' of type "
                            f"'{target_info.name}' must be a scalar",
                        )
            elif target_fields != target_entity.key:
                raise PlanError(
                    "InvalidJoin",
                    f"@link target {target_fields} does not match the primary key of "
                    f"entity '{target_entity.table}'",
                )
            nested = self._compile_fields(
                target_info, target_entity, node.selection_set, node_path
            )
            if key not in seen:
                seen.add(key)
                self.entity_keys[target_entity.table] = list(target_entity.key)
                self.key_types[target_entity.table] = [
                    target_info.fields[name].type_ref for name in target_entity.key
                ]
                children.append(
                    ExecNode(
                        key,
                        node.name,
                        field.type_ref,
                        required=required,
                        is_list=is_list,
                        local=list(local),
                        local_types=[info.fields[n].type_ref for n in local],
                        target=list(target_fields),
                        target_types=[
                            target_info.fields[n].type_ref for n in target_fields
                        ],
                        target_table=target_entity.table,
                        children=nested,
                    )
                )
        return children


def _is_scalar_value_field(schema: Schema, field) -> bool:
    """Whether a field holds a single (non-list) scalar value."""
    if field is None:
        return False
    return (
        not _is_list_type(field.type_ref)
        and named_of(field.type_ref) in schema.scalars
    )


# ---------------------------------------------------------------------------
# Event folding
# ---------------------------------------------------------------------------


def fold_events(ctx: ExecContext, events_text: str, source: str) -> None:
    """Parse and validate every event line, then fold them into snapshots."""
    events: List[Tuple[int, Dict[str, Any]]] = []
    for lineno, raw in enumerate(events_text.splitlines(), 1):
        line = raw.strip()
        if not line:
            continue
        events.append((lineno, _parse_event(line, source, lineno)))

    for lineno, event in events:
        _apply_event(ctx, event, source, lineno)


def _parse_event(line: str, source: str, lineno: int) -> Dict[str, Any]:
    try:
        event = json.loads(line)
    except json.JSONDecodeError as exc:
        raise PlanError("EventError", f"{source}:{lineno}: invalid JSON: {exc.msg}")
    if not isinstance(event, dict):
        raise PlanError("EventError", f"{source}:{lineno}: event must be a JSON object")
    for key in ("op", "entity", "before", "after"):
        if key not in event:
            raise PlanError(
                "EventError", f"{source}:{lineno}: event is missing '{key}'"
            )
    if event["op"] not in EVENT_OPS:
        raise PlanError(
            "EventError", f"{source}:{lineno}: unknown op {event['op']!r}"
        )
    if not isinstance(event["entity"], str) or not event["entity"]:
        raise PlanError(
            "EventError", f"{source}:{lineno}: 'entity' must be a non-empty string"
        )
    for key in ("before", "after"):
        if event[key] is not None and not isinstance(event[key], dict):
            raise PlanError(
                "EventError", f"{source}:{lineno}: '{key}' must be an object or null"
            )
    return event


def _apply_event(
    ctx: ExecContext, event: Dict[str, Any], source: str, lineno: int
) -> None:
    """Maintain the current snapshot store for one validated event.

    Events for entities the query cannot reach are ignored (as in
    subscription-push); for every reachable entity the operative snapshot
    must carry a well-formed scalar primary key.
    """
    key_fields = ctx.entity_keys.get(event["entity"])
    if key_fields is None:
        return
    op = event["op"]
    if op in ("INSERT", "UPDATE"):
        snapshot = event["after"]
        if snapshot is None:
            raise PlanError(
                "EventError",
                f"{source}:{lineno}: {op} event requires an 'after' snapshot",
            )
        key = _require_key(
            key_fields, ctx.key_types[event["entity"]], snapshot,
            event["entity"], ctx.schema, source, lineno,
        )
        ctx.snapshots.setdefault(event["entity"], _OrderedStore()).upsert(key, snapshot)
        return
    snapshot = event["before"]
    if snapshot is None:
        raise PlanError(
            "EventError",
            f"{source}:{lineno}: DELETE event requires a 'before' snapshot",
        )
    key = _require_key(
        key_fields, ctx.key_types[event["entity"]], snapshot,
        event["entity"], ctx.schema, source, lineno,
    )
    ctx.snapshots.setdefault(event["entity"], _OrderedStore()).delete(key)


def _require_key(
    key_fields: List[str],
    key_types: List[Any],
    snapshot: Dict[str, Any],
    table: str,
    schema: Schema,
    source: str,
    lineno: int,
) -> Tuple[Any, ...]:
    """Build a primary-key tuple, rejecting any malformed or incomplete one."""
    values: List[Any] = []
    for name, type_ref in zip(key_fields, key_types):
        if name not in snapshot:
            raise PlanError(
                "EventError",
                f"{source}:{lineno}: snapshot of entity '{table}' is missing "
                f"primary key field '{name}'",
            )
        value = snapshot[name]
        if value is None or isinstance(value, (dict, list)):
            raise PlanError(
                "EventError",
                f"{source}:{lineno}: primary key field '{name}' of entity '{table}' "
                f"cannot be null or a composite value",
            )
        _check_value_shape(schema, type_ref, value, f"{table}.{name}")
        values.append(value)
    return tuple(values)


# ---------------------------------------------------------------------------
# Query execution
# ---------------------------------------------------------------------------


def execute(roots: List[dict], ctx: ExecContext) -> Dict[str, Any]:
    """Answer the compiled query against the current snapshot stores."""
    data: Dict[str, Any] = {}
    for root in roots:
        if "introspection" in root:
            # No introspection data is modeled; a cost-0 introspection root is
            # answered deterministically with null.
            data[root["introspection"]] = None
            continue
        data[root["response_key"]] = _execute_root(root, ctx)
    return {"data": data}


def _execute_root(root: dict, ctx: ExecContext) -> Any:
    store = ctx.snapshots.get(root["table"])
    rows: List[Dict[str, Any]] = []
    if store is not None:
        for row in store.values():
            if _matches_filter(root, row, ctx):
                rows.append(row)
    path = root["response_key"]
    if root["is_list"]:
        return [_project(root["children"], row, ctx, path) for row in rows]
    if not rows:
        return None
    if len(rows) > 1:
        raise PlanError(
            "QueryError",
            f"single-object root field '{path}' matched {len(rows)} entities",
        )
    return _project(root["children"], rows[0], ctx, path)


def _matches_filter(root: dict, snapshot: Dict[str, Any], ctx: ExecContext) -> bool:
    for name, expected in root["filter"].items():
        if name not in snapshot:
            raise PlanError(
                "EventError",
                f"snapshot of entity '{root['table']}' is missing filter field "
                f"'{name}'",
            )
        value = snapshot[name]
        _check_value_shape(
            ctx.schema,
            root["filter_types"][name],
            value,
            f"{root['response_key']}({name})",
        )
        if value != expected:
            return False
    return True


def _project(
    nodes: List[ExecNode],
    snapshot: Dict[str, Any],
    ctx: ExecContext,
    path: str,
) -> Dict[str, Any]:
    """Project compiled selections over one entity snapshot."""
    data: Dict[str, Any] = {}
    for node in nodes:
        node_path = f"{path}.{node.response_key}"
        if node.children is None:
            if node.field_name not in snapshot:
                raise PlanError(
                    "EventError",
                    f"snapshot is missing field '{node.field_name}' for '{node_path}'",
                )
            value = snapshot[node.field_name]
            _check_value_shape(ctx.schema, node.field_type, value, node_path)
            data[node.response_key] = value
            continue
        if node.is_list:
            data[node.response_key] = _project_list(node, snapshot, ctx, node_path)
            continue
        related = _resolve_object(node, snapshot, ctx, node_path)
        if related is None:
            if node.required:
                raise PlanError(
                    "EventError",
                    f"non-null relationship '{node_path}' resolved to null",
                )
            data[node.response_key] = None
        else:
            data[node.response_key] = _project(
                node.children, related, ctx, node_path
            )
    return data


def _project_list(
    node: ExecNode,
    snapshot: Dict[str, Any],
    ctx: ExecContext,
    path: str,
) -> List[Dict[str, Any]]:
    matches = _resolve_list(node, snapshot, ctx, path)
    return [_project(node.children, related, ctx, path) for related in matches]


# -- @link resolution -----------------------------------------------------------


def _read_local(
    node: ExecNode, snapshot: Dict[str, Any], ctx: ExecContext, path: str
) -> Optional[List[Any]]:
    """Read @link local values; None means any local value is null."""
    local_values: List[Any] = []
    for name, type_ref in zip(node.local, node.local_types):
        if name not in snapshot:
            raise PlanError(
                "EventError",
                f"snapshot is missing local key field '{name}' for '{path}'",
            )
        value = snapshot[name]
        if value is None:
            return None
        if isinstance(value, (dict, list)):
            raise PlanError(
                "EventError",
                f"local key field '{name}' for '{path}' cannot form a scalar key",
            )
        _check_value_shape(ctx.schema, type_ref, value, path)
        local_values.append(value)
    return local_values


def _check_target_fields(
    node: ExecNode, related: Dict[str, Any], ctx: ExecContext, path: str
) -> None:
    """Ensure every matched target field is present with a compatible scalar."""
    for name, type_ref in zip(node.target, node.target_types):
        if name not in related:
            raise PlanError(
                "EventError",
                f"target snapshot of entity '{node.target_table}' is missing key "
                f"field '{name}' for '{path}'",
            )
        value = related[name]
        if isinstance(value, (dict, list)):
            raise PlanError(
                "EventError",
                f"target key field '{name}' for '{path}' cannot be matched as a "
                f"scalar",
            )
        if value is not None:
            _check_value_shape(ctx.schema, type_ref, value, path)


def _check_primary_key(node: ExecNode, ctx: ExecContext, related: Dict[str, Any],
                       path: str) -> None:
    """Ensure a matched target snapshot supplies a well-formed primary key."""
    key_fields = ctx.entity_keys[node.target_table]
    key_types = ctx.key_types[node.target_table]
    for name, type_ref in zip(key_fields, key_types):
        if name not in related:
            raise PlanError(
                "EventError",
                f"target snapshot of entity '{node.target_table}' for '{path}' is "
                f"missing primary key field '{name}'",
            )
        value = related[name]
        if isinstance(value, (dict, list)) or value is None:
            raise PlanError(
                "EventError",
                f"primary key field '{name}' of entity '{node.target_table}' for "
                f"'{path}' cannot be a key",
            )
        _check_value_shape(ctx.schema, type_ref, value, path)


def _resolve_object(
    node: ExecNode,
    snapshot: Dict[str, Any],
    ctx: ExecContext,
    path: str,
) -> Optional[Dict[str, Any]]:
    """Follow a single-object @link to the unique current target snapshot."""
    local_values = _read_local(node, snapshot, ctx, path)
    if local_values is None:
        return None

    target_store = ctx.snapshots.get(node.target_table)
    related = (
        _MISSING
        if target_store is None
        else target_store.rows.get(tuple(local_values), _MISSING)
    )
    if related is _MISSING:
        rendered = ", ".join(
            f"{name}: {json.dumps(value)}"
            for name, value in zip(node.target, local_values)
        )
        raise PlanError(
            "EventError",
            f"no current snapshot of entity '{node.target_table}' for '{path}' "
            f"with key {{{rendered}}}",
        )
    _check_target_fields(node, related, ctx, path)
    return related


def _resolve_list(
    node: ExecNode,
    snapshot: Dict[str, Any],
    ctx: ExecContext,
    path: str,
) -> List[Dict[str, Any]]:
    """Match all current target snapshots for a list @link, in insert order.

    An empty list stands for both an absent relationship (any local value
    null) and one without a current match.
    """
    local_values = _read_local(node, snapshot, ctx, path)
    if local_values is None:
        return []

    target_store = ctx.snapshots.get(node.target_table)
    if target_store is None:
        return []
    expected = tuple(local_values)
    matches: List[Dict[str, Any]] = []
    for related in target_store.values():
        _check_target_fields(node, related, ctx, path)
        values = tuple(related[name] for name in node.target)
        if values != expected or None in values:
            continue
        _check_primary_key(node, ctx, related, path)
        matches.append(related)
    return matches


# ---------------------------------------------------------------------------
# Scalar / enum / list shape validation against the schema
# ---------------------------------------------------------------------------


def _check_value_shape(
    schema: Schema, type_ref, value: Any, path: str
) -> None:
    """Validate a snapshot value against a field's declared shape.

    A null value is accepted for nullable positions and rejected for
    non-null ones; lists must be JSON arrays (elements checked recursively,
    honoring their own non-null wrappers) and leaf values must belong to the
    declared scalar/enum primitive family.
    """
    non_null = type_ref[0] == "non_null"
    if non_null:
        type_ref = type_ref[1]
    if value is None:
        if non_null:
            raise PlanError(
                "EventError", f"non-null field '{path}' resolved to null"
            )
        return
    if type_ref[0] == "list":
        if not isinstance(value, list):
            raise PlanError(
                "EventError",
                f"field '{path}' expects a list but the snapshot value is not an array",
            )
        for item in value:
            _check_value_shape(schema, type_ref[1], item, path)
        return
    name = type_ref[1]
    if isinstance(value, (dict, list)):
        raise PlanError(
            "EventError", f"field '{path}' cannot hold a composite value"
        )
    if name == "Int":
        if not isinstance(value, int) or isinstance(value, bool):
            raise PlanError("EventError", f"field '{path}' expects an Int value")
    elif name == "Float":
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise PlanError("EventError", f"field '{path}' expects a Float value")
    elif name == "String":
        if not isinstance(value, str):
            raise PlanError("EventError", f"field '{path}' expects a String value")
    elif name == "ID":
        if not (
            isinstance(value, str)
            or (isinstance(value, int) and not isinstance(value, bool))
        ):
            raise PlanError("EventError", f"field '{path}' expects an ID value")
    elif name == "Boolean":
        if not isinstance(value, bool):
            raise PlanError("EventError", f"field '{path}' expects a Boolean value")
    elif name in schema.enums:
        if not isinstance(value, str):
            raise PlanError(
                "EventError", f"enum field '{path}' expects a string enum value"
            )
    # Other custom scalar names accept any scalar JSON value.

"""Query complexity control.

Computes a deterministic request-complexity score from the same GraphQL
document and variables used by execution, strictly *before* any resolver,
indexed-entity read or subscription is established. Over-limit requests stop
with a single ``QUERY_COMPLEXITY_EXCEEDED`` GraphQL error without touching the
entity snapshots.

Scoring rules
-------------
* the selected operation is walked from its root selection set;
* every leaf field costs 1; a composite field costs only the sum of its
  children (the object container itself is free);
* repeated fields and distinct aliases are scored independently;
* fragments are inlined once at each spread position; an inline fragment
  contributes its selection directly;
* introspection fields ``__schema`` and ``__type`` cost 0;
* list fields scale their sub-selection by an effective item upper bound read
  from a ``first`` or ``limit`` argument -- a literal positive integer first,
  then a positive-integer variable of the same name -- falling back to
  ``DEFAULT_LIST_BOUND`` when the argument is absent, non-positive or
  non-integer. Variable values keep their GraphQL type validation from the
  existing validation phase; the scorer never rejects one (a non-integer bound
  simply means "no usable bound").

The scorer walks the raw AST rather than the planner's merged selection so the
"repeated fields count separately" requirement holds regardless of the
response-key de-duplication execution performs.
"""

from __future__ import annotations

import os
from typing import Any, Callable, Dict, List, Optional

from .errors import PlanError
from .gql import (
    FieldNode,
    FragmentSpread,
    InlineFragment,
    Var,
    parse_executable,
)
from .planner import Planner, _is_list_type
from .schema import Schema, TypeInfo, named_of

DEFAULT_LIST_BOUND = 1000
LIMIT_ENV_VAR = "GRAPHQL_QUERY_COMPLEXITY_LIMIT"

# Argument names that may supply a list item upper bound, in priority order.
BOUND_ARG_NAMES = ("first", "limit")


class QueryComplexityExceeded(PlanError):
    """The selected operation scores strictly above the configured limit.

    Rendered as a GraphQL response on stdout (``data: null`` plus a single
    error whose ``extensions.code`` is QUERY_COMPLEXITY_EXCEEDED) rather than
    the usual ``{code, message}`` stderr envelope.
    """

    def __init__(self, complexity: int, limit: int):
        super().__init__(
            "QUERY_COMPLEXITY_EXCEEDED",
            f"query complexity {complexity} exceeds the configured limit {limit}",
        )
        self.complexity = complexity
        self.limit = limit


def complexity_error_payload(complexity: int, limit: int) -> Dict[str, Any]:
    """Build the GraphQL-style response emitted for an over-limit request."""
    return {
        "data": None,
        "errors": [
            {
                "message": (
                    f"query complexity {complexity} exceeds the configured "
                    f"limit {limit}"
                ),
                "extensions": {"code": "QUERY_COMPLEXITY_EXCEEDED"},
            }
        ],
    }


def load_complexity_limit(raw: Optional[str]) -> Optional[int]:
    """Validate a GRAPHQL_QUERY_COMPLEXITY_LIMIT value.

    Returns ``None`` when the control is disabled (the variable is unset or
    ``"0"``), otherwise the positive integer limit. A negative, non-integer or
    otherwise unparseable value raises INVALID_QUERY_COMPLEXITY_LIMIT.
    """
    if raw is None:
        return None
    text = raw.strip()
    try:
        value = int(text)
    except ValueError:
        raise PlanError(
            "INVALID_QUERY_COMPLEXITY_LIMIT",
            f"value {raw!r} must be a non-negative integer",
        )
    if value < 0:
        raise PlanError(
            "INVALID_QUERY_COMPLEXITY_LIMIT",
            "query complexity limit must not be negative",
        )
    if value == 0:
        return None
    return value


def load_limit_from_env(
    environ: Optional[Dict[str, Optional[str]]] = None,
) -> Optional[int]:
    """Read and validate the limit from the process environment."""
    env = os.environ if environ is None else environ
    return load_complexity_limit(env.get(LIMIT_ENV_VAR))


class ComplexityCalculator(Planner):
    """Scores one selected operation using the planner's type knowledge.

    Only fragment type-condition matching is inherited; the selection walk is
    intentionally separate so it never merges repeated fields.
    """

    def score_operation(self, op, fragments: Dict[str, Any]) -> int:
        self.fragments = fragments
        self.var_map = {}
        for name, type_ref, default, has_default in op.var_defs:
            if name in self.var_map:
                raise PlanError(
                    "VariablesError",
                    f"variable '${name}' is declared more than once",
                )
            self.var_map[name] = (type_ref, default, has_default)

        root_name = self.schema.roots.get(op.op_type)
        root_info = self.schema.types.get(root_name) if root_name else None
        if root_info is None:
            raise PlanError(
                "UnknownField",
                f"schema does not define a root type for {op.op_type} operations",
            )
        return self._walk_set(op.selection_set, root_info, [])

    # -- list bounds ----------------------------------------------------------

    def _resolve_bound(self, value: Any) -> Optional[int]:
        """Resolve a first/limit argument to a positive integer, else None."""
        if isinstance(value, Var):
            spec = self.var_map.get(value.name)
            if spec is None:
                # An undeclared variable is reported by the regular validation
                # phase; complexity treats it as "no usable bound".
                return None
            _type_ref, default, has_default = spec
            if value.name in self.variables:
                value = self.variables[value.name]
            elif has_default:
                value = default
            else:
                return None
        if isinstance(value, bool):
            return None
        if isinstance(value, int) and value > 0:
            return value
        return None

    def _bound_for(self, node: FieldNode) -> int:
        """Effective item upper bound for a list field."""
        for arg_name in BOUND_ARG_NAMES:
            if arg_name in node.args:
                bound = self._resolve_bound(node.args[arg_name])
                return bound if bound is not None else DEFAULT_LIST_BOUND
        return DEFAULT_LIST_BOUND

    # -- selection walk -------------------------------------------------------

    def _walk_set(self, selections, info: TypeInfo, stack: List[str]) -> int:
        return sum(self._walk_one(sel, info, stack) for sel in selections)

    def _walk_one(self, sel, info: TypeInfo, stack: List[str]) -> int:
        if isinstance(sel, FieldNode):
            return self._walk_field(sel, info, stack)
        if isinstance(sel, FragmentSpread):
            frag = self.fragments.get(sel.name)
            if frag is None:
                raise PlanError(
                    "InvalidQuery", f"unknown fragment '{sel.name}'"
                )
            if sel.name in stack:
                raise PlanError(
                    "InvalidQuery", f"fragment cycle involving '{sel.name}'"
                )
            if not self._type_condition_matches(frag.type_condition, info.name):
                return 0
            frag_info = self.schema.types.get(frag.type_condition, info)
            return self._walk_set(
                frag.selection_set, frag_info, stack + [sel.name]
            )
        if isinstance(sel, InlineFragment):
            if sel.type_condition is None:
                return self._walk_set(sel.selection_set, info, stack)
            if not self._type_condition_matches(sel.type_condition, info.name):
                return 0
            inner_info = self.schema.types.get(sel.type_condition, info)
            return self._walk_set(sel.selection_set, inner_info, stack)
        return 0

    def _walk_field(self, node: FieldNode, info: TypeInfo, stack: List[str]) -> int:
        if node.name in ("__schema", "__type"):
            return 0
        field = info.fields.get(node.name)
        if field is None:
            raise PlanError(
                "UnknownField",
                f"unknown field '{node.name}' on type '{info.name}'",
            )
        type_name = named_of(field.type_ref)
        if self.schema.is_leaf(type_name):
            return 1
        target_info = self.schema.types.get(type_name)
        if target_info is None:
            raise PlanError(
                "UnknownField",
                f"field '{node.name}' has unsupported type '{type_name}'",
            )
        if node.selection_set is None:
            raise PlanError(
                "InvalidQuery", f"field '{node.name}' requires a selection set"
            )
        inner = self._walk_set(node.selection_set, target_info, stack)
        if _is_list_type(field.type_ref):
            inner *= self._bound_for(node)
        return inner


def enforce_complexity(
    schema: Schema,
    variables: Dict[str, Any],
    query_text: str,
    source: str,
    operation_name: Optional[str],
    select_operation: Callable,
    limit: int,
) -> int:
    """Re-parse the document, select the operation and enforce the limit.

    Invoked only after the command's own compiler has validated the document,
    so any GraphQL/variable/mapping error has already surfaced with its
    existing code. Raises QueryComplexityExceeded when the score is strictly
    above ``limit``; returns the score otherwise.
    """
    operations, fragments = parse_executable(query_text, source)
    op = select_operation(operations, operation_name)
    calculator = ComplexityCalculator(schema, variables)
    complexity = calculator.score_operation(op, fragments)
    if complexity > limit:
        raise QueryComplexityExceeded(complexity, limit)
    return complexity

"""Query plan builder.

Turns an executable GraphQL document plus resolved variables into a scan/join
plan over the entities declared in the schema. All validation failures raise
PlanError with the appropriate code; no partial plan is produced.
"""

from __future__ import annotations

from typing import Any, Dict, List, Optional

from .errors import PlanError
from .gql import (
    FieldNode,
    FragmentSpread,
    InlineFragment,
    Var,
    parse_executable,
)
from .schema import Schema, TypeInfo, named_of

# Field arguments accepted as list-size bounds while query complexity control
# is enabled, in priority order. Only present when a bound limit is configured,
# so baseline argument validation is unchanged when the control is off.
BOUND_ARG_NAMES = ("first", "limit")


def _is_list_type(type_ref) -> bool:
    """Whether a (possibly non-null wrapped) field type is a list."""
    if type_ref[0] == "non_null":
        type_ref = type_ref[1]
    return type_ref[0] == "list"


class Planner:
    def __init__(self, schema: Schema, variables: Dict[str, Any],
                 bound_args_allowed: bool = False):
        self.schema = schema
        self.variables = variables
        # When a complexity limit is configured, list fields accept first/limit
        # bounds (literal or variable); otherwise arguments stay unsupported.
        self.bound_args_allowed = bound_args_allowed
        self.fragments: Dict[str, Any] = {}
        self.var_map: Dict[str, tuple] = {}
        self.joins: List[dict] = []

    # -- complexity bound arguments ------------------------------------------

    def _accepts_bound_arg(self, is_list_field: bool, arg_name: str) -> bool:
        """Whether a first/limit argument is accepted on this field.

        Bound arguments are only recognized while complexity control is
        enabled and only on list-returning fields; everywhere else the field's
        ordinary argument validation (unknown argument / arguments not
        supported) keeps applying, so baseline behavior is unchanged.
        """
        return (
            self.bound_args_allowed
            and is_list_field
            and arg_name in BOUND_ARG_NAMES
        )

    # -- entry point ---------------------------------------------------------

    def plan(self, query_text: str, source: str, operation_name: Optional[str]) -> dict:
        operations, self.fragments = parse_executable(query_text, source)
        op = self._select_operation(operations, operation_name)
        self.var_map = {}
        for name, type_ref, default, has_default in op.var_defs:
            if name in self.var_map:
                raise PlanError("VariablesError", f"variable '${name}' is declared more than once")
            self.var_map[name] = (type_ref, default, has_default)

        root_type_name = self.schema.roots.get(op.op_type)
        root_type = self.schema.types.get(root_type_name) if root_type_name else None
        if root_type is None:
            raise PlanError(
                "UnknownField",
                f"schema does not define a root type for {op.op_type} operations",
            )

        selections = self._expand(op.selection_set, root_type.name, [])
        if not selections:
            raise PlanError("InvalidQuery", "operation has an empty selection set")

        plan = {
            "operationType": op.op_type,
            "operationName": op.name,
            "roots": [],
            "joins": self.joins,
        }
        for node in selections:
            plan["roots"].append(self._plan_root(node, root_type))
        return plan

    # -- operation selection ---------------------------------------------------

    @staticmethod
    def _select_operation(operations, operation_name):
        if operation_name is not None:
            for op in operations:
                if op.name == operation_name:
                    if op.op_type == "subscription":
                        raise PlanError(
                            "UnsupportedOperation",
                            "subscription operations are not supported",
                        )
                    return op
            raise PlanError("InvalidOperation", f"no operation named '{operation_name}'")
        candidates = [op for op in operations if op.op_type in ("query", "mutation")]
        if len(candidates) == 1:
            return candidates[0]
        if not operations:
            raise PlanError("InvalidRequest", "document contains no operations")
        if not candidates and len(operations) == 1:
            raise PlanError(
                "UnsupportedOperation", "subscription operations are not supported"
            )
        raise PlanError(
            "InvalidRequest",
            "multiple operations found; select one with --operation",
        )

    # -- fragment expansion ------------------------------------------------------

    def _type_condition_matches(self, condition: str, type_name: str) -> bool:
        if condition == type_name:
            return True
        info = self.schema.types.get(type_name)
        if info is not None and condition in info.interfaces:
            return True
        members = self.schema.unions.get(condition)
        return bool(members) and type_name in members

    def _expand(self, selections, type_name: str, stack: List[str]) -> List[FieldNode]:
        """Inline fragments and merge fields by response key, preserving order."""
        out: List[FieldNode] = []
        index: Dict[str, FieldNode] = {}

        def add(node: FieldNode) -> None:
            key = node.alias or node.name
            existing = index.get(key)
            if existing is None:
                index[key] = FieldNode(
                    node.name,
                    node.alias,
                    dict(node.args),
                    list(node.selection_set) if node.selection_set is not None else None,
                )
                out.append(index[key])
                return
            if existing.name != node.name:
                raise PlanError(
                    "InvalidQuery",
                    f"conflicting fields '{existing.name}' and '{node.name}' share response key '{key}'",
                )
            if (existing.selection_set is None) != (node.selection_set is None):
                raise PlanError(
                    "InvalidQuery", f"conflicting selections for response key '{key}'"
                )
            if existing.selection_set is not None:
                existing.selection_set.extend(node.selection_set)

        for sel in selections:
            if isinstance(sel, FieldNode):
                add(sel)
            elif isinstance(sel, FragmentSpread):
                frag = self.fragments.get(sel.name)
                if frag is None:
                    raise PlanError("InvalidQuery", f"unknown fragment '{sel.name}'")
                if sel.name in stack:
                    raise PlanError(
                        "InvalidQuery", f"fragment cycle involving '{sel.name}'"
                    )
                if self._type_condition_matches(frag.type_condition, type_name):
                    for node in self._expand(frag.selection_set, type_name, stack + [sel.name]):
                        add(node)
            elif isinstance(sel, InlineFragment):
                if sel.type_condition is None or self._type_condition_matches(
                    sel.type_condition, type_name
                ):
                    for node in self._expand(sel.selection_set, type_name, stack):
                        add(node)
        return out

    # -- variables ------------------------------------------------------------

    def _resolve(self, value: Any) -> Any:
        if isinstance(value, Var):
            name = value.name
            if name not in self.var_map:
                raise PlanError(
                    "VariablesError", f"variable '${name}' is not declared by the operation"
                )
            type_ref, default, has_default = self.var_map[name]
            if name in self.variables:
                provided = self.variables[name]
                if not self._check_type(type_ref, provided):
                    raise PlanError(
                        "VariablesError",
                        f"variable '${name}' has a value of the wrong type",
                    )
                return provided
            if has_default:
                return default
            raise PlanError("VariablesError", f"variable '${name}' was not provided")
        if isinstance(value, list):
            return [self._resolve(item) for item in value]
        if isinstance(value, dict):
            return {key: self._resolve(item) for key, item in value.items()}
        return value

    def _check_type(self, type_ref, value) -> bool:
        kind = type_ref[0]
        if kind == "non_null":
            return value is not None and self._check_type(type_ref[1], value)
        if value is None:
            return True
        if kind == "list":
            return isinstance(value, list) and all(
                self._check_type(type_ref[1], item) for item in value
            )
        name = type_ref[1]
        if name == "Int":
            return isinstance(value, int) and not isinstance(value, bool)
        if name == "Float":
            return isinstance(value, (int, float)) and not isinstance(value, bool)
        if name == "String":
            return isinstance(value, str)
        if name == "Boolean":
            return isinstance(value, bool)
        if name == "ID":
            return isinstance(value, (str, int)) and not isinstance(value, bool)
        if name in self.schema.scalars:
            return True
        if name in self.schema.enums:
            return isinstance(value, str)
        input_def = self.schema.inputs.get(name)
        if input_def is not None:
            if not isinstance(value, dict):
                return False
            for field_name, field_def in input_def.items():
                if (
                    field_def.type[0] == "non_null"
                    and not field_def.has_default
                    and field_name not in value
                ):
                    return False
                if field_name in value and not self._check_type(
                    field_def.type, value[field_name]
                ):
                    return False
            return True
        return True  # unknown named type: accept

    # -- roots ------------------------------------------------------------------

    def _plan_root(self, node: FieldNode, root_type: TypeInfo) -> dict:
        key = node.alias or node.name
        field = root_type.fields.get(node.name)
        if field is None:
            raise PlanError(
                "UnknownField", f"unknown root field '{node.name}' on type '{root_type.name}'"
            )
        type_name = named_of(field.type_ref)
        target = self.schema.types.get(type_name)
        entity = target.entity if target is not None else None
        if entity is None:
            raise PlanError(
                "UnknownEntity",
                f"root field '{node.name}' does not return a mapped entity type",
            )
        if node.selection_set is None:
            raise PlanError(
                "InvalidQuery", f"root field '{node.name}' requires a selection set"
            )
        for arg_name, arg_def in field.args.items():
            if (
                arg_def.type[0] == "non_null"
                and not arg_def.has_default
                and arg_name not in node.args
            ):
                raise PlanError(
                    "UnknownField",
                    f"missing required argument '{arg_name}' on root field '{node.name}'",
                )
        filter_obj: Dict[str, Any] = {}
        for arg_name, value in node.args.items():
            if arg_name not in field.args:
                raise PlanError(
                    "UnknownField",
                    f"unknown argument '{arg_name}' on root field '{node.name}'",
                )
            target_field = target.fields.get(arg_name)
            if target_field is None or not self.schema.is_leaf(
                named_of(target_field.type_ref)
            ):
                raise PlanError(
                    "UnknownField",
                    f"argument '{arg_name}' does not match a filterable field of entity '{entity.table}'",
                )
            filter_obj[arg_name] = self._resolve(value)
        entry = {"path": key, "entity": entity.table, "filter": filter_obj, "fields": []}
        self._walk(target, entity, node.selection_set, key, entry)
        return entry

    # -- nested selections --------------------------------------------------------

    def _walk(self, info: TypeInfo, entity, selection_set, path: str, entry: dict) -> None:
        selections = self._expand(selection_set, info.name, [])
        if not selections:
            raise PlanError("InvalidQuery", f"empty selection set at '{path}'")
        for node in selections:
            key = node.alias or node.name
            node_path = f"{path}.{key}"
            field = info.fields.get(node.name)
            if field is None:
                raise PlanError(
                    "UnknownField", f"unknown field '{node.name}' on type '{info.name}'"
                )
            type_name = named_of(field.type_ref)
            if self.schema.is_leaf(type_name):
                if node.selection_set is not None:
                    raise PlanError(
                        "InvalidQuery",
                        f"scalar field '{node.name}' must not have a selection set",
                    )
                if node.args:
                    raise PlanError(
                        "InvalidQuery",
                        f"arguments on field '{node.name}' are not supported",
                    )
                if node_path not in entry["fields"]:
                    entry["fields"].append(node_path)
                continue
            target = self.schema.types.get(type_name)
            if target is None:
                raise PlanError(
                    "UnknownField",
                    f"field '{node.name}' has unsupported type '{type_name}'",
                )
            if node.args:
                raise PlanError(
                    "InvalidQuery",
                    f"arguments on field '{node.name}' are not supported",
                )
            if node.selection_set is None:
                raise PlanError(
                    "InvalidQuery", f"field '{node.name}' requires a selection set"
                )
            if field.link is None:
                raise PlanError(
                    "MappingError",
                    f"field '{info.name}.{node.name}' is missing an @link directive",
                )
            target_entity = target.entity
            if target_entity is None:
                raise PlanError(
                    "UnknownEntity",
                    f"type '{target.name}' is not mapped to an entity",
                )
            local, target_key, as_array = field.link
            if target_key != target_entity.key:
                raise PlanError(
                    "InvalidJoin",
                    f"@link target {target_key} does not match the primary key of entity '{target_entity.table}'",
                )
            self.joins.append(
                {
                    "path": node_path,
                    "fromEntity": entity.table,
                    "fromField": local if as_array else local[0],
                    "toEntity": target_entity.table,
                    "toField": target_key if as_array else target_key[0],
                }
            )
            self._walk(target, target_entity, node.selection_set, node_path, entry)

"""Subscription push: match entity change events against a subscription.

Compiles a subscription operation into an equality filter plus a field
projection over a single @entity root, then applies it to an NDJSON stream of
entity change events. GraphQL, variable and @entity mapping semantics are
shared with the query planner; the supported selection shape covers leaf
fields, nested object fields and nested list fields reached through @link
joins (one or more levels deep, including aliases and fragment spreads).

List fields match every current target snapshot whose @link target field
values equal the source's local field values; the matched targets are
recursively projected in target insert order. The @link target of a list
relationship need not be (part of) the target entity's primary key.
"""

from __future__ import annotations

import json
from typing import Any, Dict, List, Optional, Tuple

from .errors import PlanError
from .gql import Var, parse_executable
from .planner import Planner, _is_list_type
from .schema import Entity, TypeInfo, named_of

EVENT_OPS = ("INSERT", "UPDATE", "DELETE")

_MISSING = object()


class SubscriptionPlan:
    """A compiled subscription ready to filter and project event snapshots."""

    __slots__ = (
        "operation_name",
        "path",
        "entity_table",
        "entity_keys",
        "filter",
        "tree",
    )

    def __init__(
        self,
        operation_name: Optional[str],
        path: str,
        entity_table: str,
        entity_keys: Dict[str, List[str]],
        filter_obj: Dict[str, Any],
        tree: "LinkedField",
    ):
        self.operation_name = operation_name
        self.path = path
        self.entity_table = entity_table
        # entity table -> primary key field names, in declared order, for the
        # root entity and every entity reachable through selected @link fields
        self.entity_keys = entity_keys
        self.filter = filter_obj  # entity field name -> expected value
        self.tree = tree  # compiled selection tree rooted at the root field

    def matches(self, snapshot: Dict[str, Any]) -> bool:
        for name, expected in self.filter.items():
            if name not in snapshot:
                raise PlanError(
                    "EventError", f"snapshot is missing filter field '{name}'"
                )
            if snapshot[name] != expected:
                return False
        return True


class LinkedField:
    """A compiled field in the subscription selection tree.

    Leaf fields carry ``field_name`` and no children. Link fields carry the
    validated @link mapping (local/target field names, target entity) and a
    list of compiled children; ``is_list`` selects list (ordered, possibly
    many) rather than single-object resolution.
    """

    __slots__ = (
        "response_key",
        "field_name",
        "required",
        "is_list",
        "local",
        "target",
        "target_table",
        "children",
    )

    def __init__(
        self,
        response_key: str,
        field_name: str,
        required: bool = False,
        is_list: bool = False,
        local: Optional[List[str]] = None,
        target: Optional[List[str]] = None,
        target_table: Optional[str] = None,
        children: Optional[List["LinkedField"]] = None,
    ):
        self.response_key = response_key
        self.field_name = field_name
        self.required = required  # field declared as a non-null object type
        self.is_list = is_list
        self.local = local  # source-side key field names, in @link order
        self.target = target  # target-side matched field names, in @link order
        self.target_table = target_table
        self.children = children


class SubscriptionCompiler(Planner):
    """Reuses the planner's fragment expansion and variable resolution."""

    def __init__(self, schema, variables, bound_args_allowed: bool = False):
        super().__init__(schema, variables, bound_args_allowed)

    def compile(
        self, subscription_text: str, source: str, operation_name: Optional[str]
    ) -> SubscriptionPlan:
        operations, self.fragments = parse_executable(subscription_text, source)
        op = self._select_operation(operations, operation_name)
        self.var_map = {}
        for name, type_ref, default, has_default in op.var_defs:
            if name in self.var_map:
                raise PlanError(
                    "VariablesError", f"variable '${name}' is declared more than once"
                )
            self.var_map[name] = (type_ref, default, has_default)

        root_type_name = self.schema.roots.get("subscription")
        root_type = self.schema.types.get(root_type_name) if root_type_name else None
        if root_type is None:
            raise PlanError(
                "MappingError",
                "schema does not define a root type for subscription operations",
            )

        selections = self._expand(op.selection_set, root_type.name, [])
        if not selections:
            raise PlanError("InvalidQuery", "subscription has an empty selection set")
        if len(selections) != 1:
            raise PlanError(
                "InvalidQuery", "subscription must select exactly one root field"
            )
        node = selections[0]
        key = node.alias or node.name

        field = root_type.fields.get(node.name)
        if field is None:
            raise PlanError(
                "InvalidQuery",
                f"unknown root field '{node.name}' on type '{root_type.name}'",
            )
        type_name = named_of(field.type_ref)
        target = self.schema.types.get(type_name)
        entity = target.entity if target is not None else None
        if entity is None:
            raise PlanError(
                "MappingError",
                f"root field '{node.name}' does not return a mapped entity type",
            )
        if node.selection_set is None:
            raise PlanError(
                "InvalidQuery", f"root field '{node.name}' requires a selection set"
            )

        filter_obj = self._compile_filter(field, target, entity.table, node)
        entity_keys: Dict[str, List[str]] = {entity.table: list(entity.key)}
        children = self._compile_fields(
            target, entity, node.selection_set, key, entity_keys
        )
        tree = LinkedField(key, key, children=children)
        return SubscriptionPlan(
            op.name, key, entity.table, entity_keys, filter_obj, tree
        )

    # -- operation selection ---------------------------------------------------

    @staticmethod
    def _select_operation(operations, operation_name):
        if operation_name is not None:
            for op in operations:
                if op.name == operation_name and op.op_type == "subscription":
                    return op
            raise PlanError(
                "InvalidQuery", f"no subscription named '{operation_name}'"
            )
        if not operations:
            raise PlanError("InvalidQuery", "document contains no operations")
        if len(operations) != 1:
            raise PlanError(
                "InvalidQuery",
                "multiple operations found; select one with --operation",
            )
        op = operations[0]
        if op.op_type != "subscription":
            raise PlanError("InvalidQuery", "operation must be a subscription")
        return op

    # -- filter ------------------------------------------------------------------

    def _compile_filter(self, field, target, table, node) -> Dict[str, Any]:
        for arg_name, arg_def in field.args.items():
            if (
                arg_def.type[0] == "non_null"
                and not arg_def.has_default
                and arg_name not in node.args
            ):
                raise PlanError(
                    "InvalidQuery",
                    f"missing required argument '{arg_name}' on root field '{node.name}'",
                )
        is_list = _is_list_type(field.type_ref)
        filter_obj: Dict[str, Any] = {}
        for arg_name, value in node.args.items():
            if self._accepts_bound_arg(is_list, arg_name):
                # A list-size bound used for complexity; never a filter. If it
                # is a variable, resolve it so type/required-variable errors
                # are reported by the normal validation phase.
                if isinstance(value, Var):
                    self._resolve(value)
                continue
            if arg_name not in field.args:
                raise PlanError(
                    "InvalidQuery",
                    f"unknown argument '{arg_name}' on root field '{node.name}'",
                )
            target_field = target.fields.get(arg_name)
            if target_field is None or not self.schema.is_leaf(
                named_of(target_field.type_ref)
            ):
                raise PlanError(
                    "InvalidQuery",
                    f"argument '{arg_name}' does not match a filterable field of entity '{table}'",
                )
            filter_obj[arg_name] = self._resolve(value)
        return filter_obj

    # -- selection tree -----------------------------------------------------------

    def _compile_fields(
        self,
        info: TypeInfo,
        entity: Entity,
        selection_set,
        path: str,
        entity_keys: Dict[str, List[str]],
    ) -> List[LinkedField]:
        selections = self._expand(selection_set, info.name, [])
        if not selections:
            raise PlanError("InvalidQuery", f"empty selection set at '{path}'")
        children: List[LinkedField] = []
        seen = set()
        for node in selections:
            key = node.alias or node.name
            node_path = f"{path}.{key}"
            field = info.fields.get(node.name)
            if field is None:
                raise PlanError(
                    "InvalidQuery",
                    f"unknown field '{node.name}' on type '{info.name}'",
                )
            type_name = named_of(field.type_ref)
            if self.schema.is_leaf(type_name):
                if node.selection_set is not None:
                    raise PlanError(
                        "InvalidQuery",
                        f"scalar field '{node.name}' must not have a selection set",
                    )
                if node.args:
                    raise PlanError(
                        "InvalidQuery",
                        f"arguments on field '{node.name}' are not supported",
                    )
                if key not in seen:
                    seen.add(key)
                    children.append(LinkedField(key, node.name))
                continue
            is_list = _is_list_type(field.type_ref)
            for arg_name, value in node.args.items():
                if self._accepts_bound_arg(is_list, arg_name):
                    if isinstance(value, Var):
                        self._resolve(value)
                    continue
                raise PlanError(
                    "InvalidQuery",
                    f"arguments on field '{node.name}' are not supported",
                )
            if node.selection_set is None:
                raise PlanError(
                    "InvalidQuery", f"field '{node.name}' requires a selection set"
                )
            required = field.type_ref[0] == "non_null"
            if field.link is None:
                raise PlanError(
                    "MappingError",
                    f"field '{info.name}.{node.name}' is missing an @link directive",
                )
            target_info = self.schema.types.get(type_name)
            if target_info is None:
                raise PlanError(
                    "MappingError",
                    f"field '{info.name}.{node.name}' has unsupported type '{type_name}'",
                )
            target_entity = target_info.entity
            if target_entity is None:
                raise PlanError(
                    "UnknownEntity",
                    f"type '{target_info.name}' is not mapped to an entity",
                )
            local, target_key, _as_array = field.link
            if is_list:
                # A list relationship matches equality on arbitrary scalar
                # target fields (they need not form the target primary key),
                # so every matched field must hold a single scalar value.
                for name in local:
                    matched_local = info.fields.get(name)
                    if not _is_scalar_value_field(self.schema, matched_local):
                        raise PlanError(
                            "MappingError",
                            f"@link local field '{name}' of type '{info.name}' "
                            f"must be a scalar",
                        )
                for name in target_key:
                    matched = target_info.fields.get(name)
                    if matched is None:
                        raise PlanError(
                            "MappingError",
                            f"@link target field '{name}' is not a field of type "
                            f"'{target_info.name}'",
                        )
                    if not _is_scalar_value_field(self.schema, matched):
                        raise PlanError(
                            "MappingError",
                            f"@link target field '{name}' of type "
                            f"'{target_info.name}' must be a scalar",
                        )
            elif target_key != target_entity.key:
                raise PlanError(
                    "InvalidJoin",
                    f"@link target {target_key} does not match the primary key of "
                    f"entity '{target_entity.table}'",
                )
            nested = self._compile_fields(
                target_info,
                target_entity,
                node.selection_set,
                node_path,
                entity_keys,
            )
            if key not in seen:
                seen.add(key)
                entity_keys[target_entity.table] = list(target_entity.key)
                children.append(
                    LinkedField(
                        key,
                        node.name,
                        required=required,
                        is_list=is_list,
                        local=list(local),
                        target=list(target_key),
                        target_table=target_entity.table,
                        children=nested,
                    )
                )
        return children


def _is_scalar_value_field(schema, field) -> bool:
    """Whether a field holds a single (non-list) built-in/custom scalar."""
    if field is None:
        return False
    return (
        not _is_list_type(field.type_ref)
        and named_of(field.type_ref) in schema.scalars
    )


# ---------------------------------------------------------------------------
# Event processing
# ---------------------------------------------------------------------------


class _OrderedStore:
    """Latest snapshots of one entity, kept in insert order.

    INSERT introduces a new row at the end; UPDATE replaces a row in place and
    preserves its position; DELETE removes a row, so a later re-INSERT is
    appended at the end again. Snapshots whose primary key cannot be built
    cannot participate in keyed identity (and therefore cannot be deleted by
    key); they are retained separately so a list match on non-key target
    fields can surface them as an EventError instead of silently dropping them.
    """

    __slots__ = ("rows", "keyless")

    def __init__(self):
        self.rows: Dict[Tuple[Any, ...], Dict[str, Any]] = {}
        self.keyless: List[Dict[str, Any]] = []

    def upsert(self, key: Optional[Tuple[Any, ...]], snapshot: Dict[str, Any]) -> None:
        # Dict assignment appends a new key at the end and replaces an existing
        # key's value without moving it, which is exactly the required order.
        if key is None:
            self.keyless.append(snapshot)
        else:
            self.rows[key] = snapshot

    def delete(self, key: Optional[Tuple[Any, ...]]) -> None:
        # A keyed row is removed so a later upsert re-appends it at the end; a
        # keyless DELETE cannot identify a stored row and leaves them untouched.
        if key is not None:
            self.rows.pop(key, None)

    def values(self) -> List[Dict[str, Any]]:
        return list(self.rows.values())


def push_events(
    plan: SubscriptionPlan, events_text: str, source: str
) -> List[Dict[str, Any]]:
    """Apply a compiled subscription to an NDJSON event stream, in order.

    Every line is parsed and validated first; the latest snapshot of each
    entity is then maintained by primary key, and matching root events are
    projected against the snapshots known up to and including that line.
    """
    events: List[Tuple[int, Dict[str, Any]]] = []
    for lineno, raw in enumerate(events_text.splitlines(), 1):
        line = raw.strip()
        if not line:
            continue
        events.append((lineno, _parse_event(line, source, lineno)))

    snapshots: Dict[str, _OrderedStore] = {}
    outputs: List[Dict[str, Any]] = []
    for lineno, event in events:
        _apply_event(plan.entity_keys, snapshots, event)
        if event["entity"] != plan.entity_table:
            continue
        op = event["op"]
        snapshot = event["after"] if op in ("INSERT", "UPDATE") else event["before"]
        if snapshot is None:
            raise PlanError(
                "EventError", f"{source}:{lineno}: {op} event has no snapshot"
            )
        if not plan.matches(snapshot):
            continue
        data = _project(
            plan.tree.children,
            snapshot,
            snapshots,
            plan.entity_keys,
            source,
            lineno,
            plan.path,
        )
        outputs.append(
            {
                "subscription": plan.operation_name,
                "path": plan.path,
                "event": op,
                "entity": event["entity"],
                "data": data,
            }
        )
    return outputs


def _apply_event(
    entity_keys: Dict[str, List[str]],
    snapshots: Dict[str, _OrderedStore],
    event: Dict[str, Any],
) -> None:
    """Update the latest-snapshot store for one validated event.

    Events for entities the subscription cannot reach are ignored. Rows whose
    snapshot lacks a usable primary key cannot identify an entity; they are
    skipped here and surface as an EventError when a matching root event tries
    to traverse the relationship, rather than at their own line.
    """
    key_fields = entity_keys.get(event["entity"])
    if key_fields is None:
        return
    store = snapshots.setdefault(event["entity"], _OrderedStore())
    if event["op"] in ("INSERT", "UPDATE"):
        snapshot = event["after"]
        if snapshot is not None:
            store.upsert(_key_tuple(key_fields, snapshot), snapshot)
        return
    snapshot = event["before"]
    if snapshot is not None:
        store.delete(_key_tuple(key_fields, snapshot))


def _key_tuple(
    key_fields: List[str], snapshot: Optional[Dict[str, Any]]
) -> Optional[Tuple[Any, ...]]:
    """Build a primary-key tuple, or None when the snapshot cannot supply one."""
    if not isinstance(snapshot, dict):
        return None
    values: List[Any] = []
    for name in key_fields:
        value = snapshot.get(name)
        if value is None or isinstance(value, (dict, list)):
            return None
        values.append(value)
    return tuple(values)


def _project(
    nodes: List[LinkedField],
    snapshot: Dict[str, Any],
    snapshots: Dict[str, _OrderedStore],
    entity_keys: Dict[str, List[str]],
    source: str,
    lineno: int,
    path: str,
) -> Dict[str, Any]:
    """Project compiled selections over one entity snapshot."""
    data: Dict[str, Any] = {}
    for node in nodes:
        node_path = f"{path}.{node.response_key}"
        if node.children is None:
            if node.field_name not in snapshot:
                raise PlanError(
                    "EventError",
                    f"{source}:{lineno}: snapshot is missing field "
                    f"'{node.field_name}'",
                )
            data[node.response_key] = snapshot[node.field_name]
            continue
        if node.is_list:
            data[node.response_key] = _project_list(
                node, snapshot, snapshots, entity_keys, source, lineno, node_path
            )
            continue
        related = _resolve_object(node, snapshot, snapshots, source, lineno, node_path)
        if related is None:
            if node.required:
                raise PlanError(
                    "EventError",
                    f"{source}:{lineno}: non-null relationship '{node_path}' "
                    f"resolved to null",
                )
            data[node.response_key] = None
        else:
            data[node.response_key] = _project(
                node.children,
                related,
                snapshots,
                entity_keys,
                source,
                lineno,
                node_path,
            )
    return data


def _project_list(
    node: LinkedField,
    snapshot: Dict[str, Any],
    snapshots: Dict[str, _OrderedStore],
    entity_keys: Dict[str, List[str]],
    source: str,
    lineno: int,
    path: str,
) -> List[Dict[str, Any]]:
    """Resolve a list @link and project each matched target snapshot."""
    matches = _resolve_list(
        node, snapshot, snapshots, entity_keys, source, lineno, path
    )
    return [
        _project(
            node.children,
            related,
            snapshots,
            entity_keys,
            source,
            lineno,
            path,
        )
        for related in matches
    ]


def _read_local(
    node: LinkedField,
    snapshot: Dict[str, Any],
    source: str,
    lineno: int,
    path: str,
) -> Optional[List[Any]]:
    """Read the @link local key values from a source snapshot.

    Returns None when any local value is null (the relationship itself is
    absent). Missing local key fields or values that cannot form a scalar key
    end the stream with EventError.
    """
    local_values: List[Any] = []
    for name in node.local:
        if name not in snapshot:
            raise PlanError(
                "EventError",
                f"{source}:{lineno}: snapshot is missing local key field "
                f"'{name}' for '{path}'",
            )
        value = snapshot[name]
        if value is None:
            return None
        if isinstance(value, (dict, list)):
            raise PlanError(
                "EventError",
                f"{source}:{lineno}: local key field '{name}' for '{path}' "
                f"cannot form a scalar key",
            )
        local_values.append(value)
    return local_values


def _check_target_fields(
    node: LinkedField,
    related: Dict[str, Any],
    source: str,
    lineno: int,
    path: str,
) -> None:
    """Ensure every matched target field is present (and scalar) on a snapshot."""
    for name in node.target:
        if name not in related:
            raise PlanError(
                "EventError",
                f"{source}:{lineno}: target snapshot is missing key field "
                f"'{name}' for '{path}'",
            )
        if isinstance(related[name], (dict, list)):
            raise PlanError(
                "EventError",
                f"{source}:{lineno}: target key field '{name}' for '{path}' "
                f"cannot be matched as a scalar",
            )


def _check_primary_key(
    table: str,
    key_fields: List[str],
    related: Dict[str, Any],
    source: str,
    lineno: int,
    path: str,
) -> None:
    """Ensure a matched target snapshot supplies its scalar primary key."""
    for name in key_fields:
        if name not in related:
            raise PlanError(
                "EventError",
                f"{source}:{lineno}: target snapshot of entity '{table}' for "
                f"'{path}' is missing primary key field '{name}'",
            )
        if isinstance(related[name], (dict, list)):
            raise PlanError(
                "EventError",
                f"{source}:{lineno}: primary key field '{name}' of entity "
                f"'{table}' for '{path}' cannot be a key",
            )


def _resolve_object(
    node: LinkedField,
    snapshot: Dict[str, Any],
    snapshots: Dict[str, _OrderedStore],
    source: str,
    lineno: int,
    path: str,
) -> Optional[Dict[str, Any]]:
    """Follow one single-object @link to the latest target snapshot.

    Returns None when any local key value is null (the relationship itself is
    absent). Missing local key fields, values that cannot form the target
    primary key or a target key without a current snapshot end the stream with
    EventError.
    """
    local_values = _read_local(node, snapshot, source, lineno, path)
    if local_values is None:
        return None

    target_store = snapshots.get(node.target_table)
    related = (
        _MISSING
        if target_store is None
        else target_store.rows.get(tuple(local_values), _MISSING)
    )
    if related is _MISSING:
        rendered = ", ".join(
            f"{name}: {json.dumps(value)}"
            for name, value in zip(node.target, local_values)
        )
        raise PlanError(
            "EventError",
            f"{source}:{lineno}: no current snapshot of entity "
            f"'{node.target_table}' for '{path}' with key {{{rendered}}}",
        )
    _check_target_fields(node, related, source, lineno, path)
    return related


def _resolve_list(
    node: LinkedField,
    snapshot: Dict[str, Any],
    snapshots: Dict[str, _OrderedStore],
    entity_keys: Dict[str, List[str]],
    source: str,
    lineno: int,
    path: str,
) -> List[Dict[str, Any]]:
    """Match all current target snapshots for a list @link, in insert order.

    An empty list stands for both an absent relationship (any local value
    null) and a relationship without a current match. Local key fields that
    are missing or non-scalar, and matched target snapshots that lack a target
    field or a usable primary key, end the stream with EventError.
    """
    local_values = _read_local(node, snapshot, source, lineno, path)
    if local_values is None:
        return []

    target_store = snapshots.get(node.target_table)
    if target_store is None:
        return []
    pk_fields = entity_keys[node.target_table]
    expected = tuple(local_values)
    matches: List[Dict[str, Any]] = []
    candidates = list(target_store.rows.values()) + list(target_store.keyless)
    for related in candidates:
        _check_target_fields(node, related, source, lineno, path)
        values = tuple(related[name] for name in node.target)
        if values != expected or None in values:
            continue
        _check_primary_key(
            node.target_table, pk_fields, related, source, lineno, path
        )
        matches.append(related)
    return matches


def _parse_event(line: str, source: str, lineno: int) -> Dict[str, Any]:
    try:
        event = json.loads(line)
    except json.JSONDecodeError as exc:
        raise PlanError("EventError", f"{source}:{lineno}: invalid JSON: {exc.msg}")
    if not isinstance(event, dict):
        raise PlanError("EventError", f"{source}:{lineno}: event must be a JSON object")
    for key in ("op", "entity", "before", "after"):
        if key not in event:
            raise PlanError(
                "EventError", f"{source}:{lineno}: event is missing '{key}'"
            )
    if event["op"] not in EVENT_OPS:
        raise PlanError(
            "EventError", f"{source}:{lineno}: unknown op {event['op']!r}"
        )
    if not isinstance(event["entity"], str):
        raise PlanError(
            "EventError", f"{source}:{lineno}: 'entity' must be a string"
        )
    for key in ("before", "after"):
        if event[key] is not None and not isinstance(event[key], dict):
            raise PlanError(
                "EventError", f"{source}:{lineno}: '{key}' must be an object or null"
            )
    return event

