"""GraphQL introspection support for ``query-exec``.

Implements the standard introspection root fields ``__schema`` and
``__type(name: String!)`` plus the meta-types they return
(``__Schema`` / ``__Type`` / ``__Field`` / ``__InputValue`` /
``__EnumValue`` / ``__Directive`` and the ``__TypeKind`` /
``__DirectiveLocation`` enums).

A query selection is compiled and validated against the fixed meta-schema
exactly like an ordinary selection (unknown fields, bad arguments, missing or
forbidden selection sets all end with ``InvalidQuery``); the resolver then
emits only the requested fields, so unrequested relationships never appear.
"""

from __future__ import annotations

import json
from typing import Any, Callable, Dict, List, Optional

from .errors import PlanError
from .gql import (
    EnumLiteral,
    FieldNode,
    FragmentSpread,
    InlineFragment,
)
from .schema import BUILTIN_SCALARS, Schema

# Meta-type names reachable as selection targets.
META_TYPE_NAMES = (
    "__Schema",
    "__Type",
    "__Field",
    "__InputValue",
    "__EnumValue",
    "__Directive",
    "__TypeKind",
    "__DirectiveLocation",
)

# (shape, child meta type, descriptor attribute)
# shape: "leaf" (scalar/enum scalar), "object" (nullable __Type-like),
# "list" (list of child objects), "strlist" (list of plain enum strings).
_META_FIELDS: Dict[str, Dict[str, tuple]] = {
    "__Schema": {
        "description": ("leaf", None, "description"),
        "types": ("list", "__Type", "types"),
        "queryType": ("object", "__Type", "queryType"),
        "mutationType": ("object", "__Type", "mutationType"),
        "subscriptionType": ("object", "__Type", "subscriptionType"),
        "directives": ("list", "__Directive", "directives"),
    },
    "__Type": {
        "kind": ("leaf", None, "kind"),
        "name": ("leaf", None, "name"),
        "description": ("leaf", None, "description"),
        "fields": ("list", "__Field", "fields"),
        "interfaces": ("list", "__Type", "interfaces"),
        "possibleTypes": ("list", "__Type", "possibleTypes"),
        "enumValues": ("list", "__EnumValue", "enumValues"),
        "inputFields": ("list", "__InputValue", "inputFields"),
        "ofType": ("object", "__Type", "ofType"),
    },
    "__Field": {
        "name": ("leaf", None, "name"),
        "description": ("leaf", None, "description"),
        "args": ("list", "__InputValue", "args"),
        "type": ("object", "__Type", "type"),
        "isDeprecated": ("leaf", None, "isDeprecated"),
        "deprecationReason": ("leaf", None, "deprecationReason"),
    },
    "__InputValue": {
        "name": ("leaf", None, "name"),
        "description": ("leaf", None, "description"),
        "type": ("object", "__Type", "type"),
        "defaultValue": ("leaf", None, "defaultValue"),
    },
    "__EnumValue": {
        "name": ("leaf", None, "name"),
        "description": ("leaf", None, "description"),
        "isDeprecated": ("leaf", None, "isDeprecated"),
        "deprecationReason": ("leaf", None, "deprecationReason"),
    },
    "__Directive": {
        "name": ("leaf", None, "name"),
        "description": ("leaf", None, "description"),
        "locations": ("strlist", None, "locations"),
        "args": ("list", "__InputValue", "args"),
        "isRepeatable": ("leaf", None, "isRepeatable"),
    },
}

# Arguments declared by introspection fields; anything else is undeclared.
_DECLARED_ARGS: Dict[str, frozenset] = {
    ("__Type", "fields"): frozenset({"includeDeprecated"}),
    ("__Type", "enumValues"): frozenset({"includeDeprecated"}),
}

BUILTIN_SCALAR_ORDER = ("Int", "Float", "String", "Boolean", "ID")

# Standard directives, in deterministic order (user directive definitions are
# accepted by the SDL parser but not retained, so only the builtins surface).
_BUILTIN_DIRECTIVES = (
    ("skip", "Directs the executor to skip this field or fragment when the `if` argument is true.",
     ("FIELD", "FRAGMENT_SPREAD", "INLINE_FRAGMENT"),
     (("if", "Skipped when true.", "Boolean!", False, None),), False),
    ("include", "Directs the executor to include this field or fragment only when the `if` argument is true.",
     ("FIELD", "FRAGMENT_SPREAD", "INLINE_FRAGMENT"),
     (("if", "Included when true.", "Boolean!", False, None),), False),
    ("deprecated", "Marks an element of a GraphQL schema as no longer supported.",
     ("FIELD_DEFINITION", "ENUM_VALUE"),
     (("reason", "Explains why this element was deprecated, usually also including a suggestion for how to access supported similar data. Formatted using the Markdown language, as specified by [CommonMark](https://commonmark.org/).",
       "String", False, None),), False),
)


# ---------------------------------------------------------------------------
# Default-value serialization
# ---------------------------------------------------------------------------


def _serialize_default(value: Any) -> str:
    """Render a const-parsed value as GraphQL input syntax (for defaultValue)."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, EnumLiteral):
        # An enum literal: must be checked before ``str``.
        return str(value)
    if isinstance(value, str):
        return json.dumps(value, ensure_ascii=False)
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return repr(value)
    if isinstance(value, list):
        return "[" + ", ".join(_serialize_default(item) for item in value) + "]"
    if isinstance(value, dict):
        return (
            "{"
            + ", ".join(
                f"{key}: {_serialize_default(item)}" for key, item in value.items()
            )
            + "}"
        )
    return json.dumps(value, ensure_ascii=False)


# ---------------------------------------------------------------------------
# Descriptor construction
# ---------------------------------------------------------------------------


class _DescriptorBuilder:
    """Builds ``__Type``/``__Field``/... descriptor dicts for one schema."""

    def __init__(self, schema: Schema):
        self.schema = schema
        self._cache: Dict[str, dict] = {}

    def build_schema(self) -> dict:
        type_names: List[str] = []
        type_names.extend(self.schema.types.keys())
        type_names.extend(self.schema.interface_fields.keys())
        type_names.extend(self.schema.unions.keys())
        type_names.extend(self.schema.enum_values.keys())
        type_names.extend(self.schema.inputs.keys())
        type_names.extend(
            sorted(self.schema.scalars.difference(BUILTIN_SCALARS))
        )
        type_names.extend(META_TYPE_NAMES)
        type_names.extend(BUILTIN_SCALAR_ORDER)

        return {
            "description": None,
            "types": [self.type_descriptor(name) for name in type_names],
            "queryType": self._root_type("query"),
            "mutationType": self._root_type("mutation"),
            "subscriptionType": self._root_type("subscription"),
            "directives": [self._directive_descriptor(d) for d in _BUILTIN_DIRECTIVES],
        }

    def _root_type(self, op: str) -> Optional[dict]:
        name = self.schema.roots.get(op)
        return self.type_descriptor(name) if name is not None else None

    def known_type(self, name: str) -> bool:
        return (
            name in self.schema.types
            or name in self.schema.interface_fields
            or name in self.schema.unions
            or name in self.schema.enum_values
            or name in self.schema.inputs
            or name in self.schema.scalars
            or name in META_TYPE_NAMES
        )

    def type_descriptor(self, name: Optional[str]) -> Optional[dict]:
        if name is None:
            return None
        cached = self._cache.get(name)
        if cached is not None:
            return cached

        schema = self.schema
        if name in schema.types:
            desc = self._object_descriptor(name)
        elif name in schema.interface_fields:
            desc = self._interface_descriptor(name)
        elif name in schema.unions:
            desc = self._union_descriptor(name)
        elif name in schema.enum_values:
            desc = self._enum_descriptor(name)
        elif name in schema.inputs:
            desc = self._input_object_descriptor(name)
        elif name in schema.scalars or name in META_TYPE_NAMES:
            desc = self._bare_descriptor("SCALAR" if name not in _META_KINDS else _META_KINDS[name], name)
        else:
            return None
        self._cache[name] = desc
        self._populate(desc, name)
        return desc

    def ref_descriptor(self, type_ref) -> dict:
        """Build a descriptor for a parsed type reference (with wrappers)."""
        kind = type_ref[0]
        if kind == "named":
            return self.type_descriptor(type_ref[1])
        wrapper_kind = "LIST" if kind == "list" else "NON_NULL"
        return self._wrapper_descriptor(wrapper_kind, self.ref_descriptor(type_ref[1]))

    def _bare_descriptor(self, kind: str, name: str) -> dict:
        return {
            "kind": kind,
            "name": name,
            "description": None,
            "fields": None,
            "interfaces": None,
            "possibleTypes": None,
            "enumValues": None,
            "inputFields": None,
            "ofType": None,
        }

    def _wrapper_descriptor(self, kind: str, of_type: Optional[dict]) -> dict:
        return {
            "kind": kind,
            "name": None,
            "description": None,
            "fields": None,
            "interfaces": None,
            "possibleTypes": None,
            "enumValues": None,
            "inputFields": None,
            "ofType": of_type,
        }

    def _object_descriptor(self, name: str) -> dict:
        desc = self._bare_descriptor("OBJECT", name)
        info = self.schema.types[name]
        desc["interfaces"] = [
            self.type_descriptor(iface) for iface in info.interfaces
        ]
        return desc

    def _interface_descriptor(self, name: str) -> dict:
        desc = self._bare_descriptor("INTERFACE", name)
        members = [
            self.type_descriptor(type_name)
            for type_name, info in self.schema.types.items()
            if name in info.interfaces
        ]
        desc["possibleTypes"] = members
        return desc

    def _union_descriptor(self, name: str) -> dict:
        desc = self._bare_descriptor("UNION", name)
        desc["possibleTypes"] = [
            self.type_descriptor(member) for member in self.schema.unions[name]
        ]
        return desc

    def _enum_descriptor(self, name: str) -> dict:
        desc = self._bare_descriptor("ENUM", name)
        desc["enumValues"] = [
            {
                "name": value,
                "description": None,
                "isDeprecated": False,
                "deprecationReason": None,
            }
            for value in self.schema.enum_values[name]
        ]
        return desc

    def _input_object_descriptor(self, name: str) -> dict:
        desc = self._bare_descriptor("INPUT_OBJECT", name)
        desc["inputFields"] = [
            self._input_value_descriptor(field_def)
            for field_def in self.schema.inputs[name].values()
        ]
        return desc

    def _populate(self, desc: dict, name: str) -> None:
        """Fill relationships that may recurse through the descriptor cache."""
        kind = desc["kind"]
        if kind == "OBJECT":
            info = self.schema.types[name]
            desc["fields"] = [
                self._field_descriptor(field) for field in info.fields.values()
            ]
        elif kind == "INTERFACE":
            desc["fields"] = [
                self._field_descriptor(field)
                for field in self.schema.interface_fields[name].values()
            ]
        elif kind == "SCALAR" and name == "__Directive":
            # Unreachable as an object selection target; nothing to populate.
            pass

    def _field_descriptor(self, field) -> dict:
        return {
            "name": field.name,
            "description": None,
            "args": [
                self._input_value_descriptor(arg_def)
                for arg_def in field.args.values()
            ],
            "type": self.ref_descriptor(field.type_ref),
            "isDeprecated": False,
            "deprecationReason": None,
        }

    def _input_value_descriptor(self, field_def) -> dict:
        default = (
            _serialize_default(field_def.default) if field_def.has_default else None
        )
        return {
            "name": field_def.name,
            "description": None,
            "type": self.ref_descriptor(field_def.type),
            "defaultValue": default,
        }

    def _directive_descriptor(self, spec) -> dict:
        name, _description, locations, args, is_repeatable = spec
        return {
            "name": name,
            "description": None,
            "locations": list(locations),
            "args": [
                {
                    "name": arg_name,
                    "description": None,
                    "type": self._type_string_ref(arg_type),
                    "defaultValue": arg_default if has_default else None,
                }
                for arg_name, _arg_desc, arg_type, has_default, arg_default in args
            ],
            "isRepeatable": is_repeatable,
        }

    def _type_string_ref(self, type_text: str) -> dict:
        """Parse a simple textual type like ``Boolean!`` into a descriptor."""
        ref: Any = ("named", type_text.rstrip("![").lstrip("[")) if "[" not in type_text else None
        # The builtin directive arguments use simple named/non-null types only.
        non_null = type_text.endswith("!")
        base = type_text[:-1] if non_null else type_text
        descriptor = self.type_descriptor(base)
        if non_null:
            descriptor = self._wrapper_descriptor("NON_NULL", descriptor)
        return descriptor


_META_KINDS = {
    "__Schema": "OBJECT",
    "__Type": "OBJECT",
    "__Field": "OBJECT",
    "__InputValue": "OBJECT",
    "__EnumValue": "OBJECT",
    "__Directive": "OBJECT",
    "__TypeKind": "ENUM",
    "__DirectiveLocation": "ENUM",
}


# ---------------------------------------------------------------------------
# Selection validation / compilation
# ---------------------------------------------------------------------------


def _invalid(message: str) -> PlanError:
    return PlanError("InvalidQuery", message)


def _merge_selections(selections, desc, fragments, stack, resolve_var):
    """Validate a selection set against one meta object descriptor.

    Returns a list of compiled entries: ``("typename", key)`` or
    ``("field", key, attribute, shape, child_entries)``.
    """
    out: List[tuple] = []
    index: Dict[str, tuple] = {}
    meta_name = desc["name"] if desc["kind"] in ("OBJECT", "ENUM") else None
    field_table = _META_FIELDS.get(meta_name or "", {})

    def add(entry: tuple) -> None:
        key = entry[1]
        existing = index.get(key)
        if existing is None:
            index[key] = entry
            out.append(entry)
            return
        if existing[0] != entry[0] or (existing[0] == "field" and existing[2] != entry[2]):
            raise _invalid(f"conflicting selections for response key '{key}'")
        if existing[0] == "field" and existing[4] is not None:
            existing[4].extend(entry[4])

    for sel in selections:
        if isinstance(sel, FragmentSpread):
            frag = fragments.get(sel.name)
            if frag is None:
                raise _invalid(f"unknown fragment '{sel.name}'")
            if sel.name in stack:
                raise _invalid(f"fragment cycle involving '{sel.name}'")
            if frag.type_condition != meta_name:
                continue
            for entry in _merge_selections(
                frag.selection_set, desc, fragments, stack + [sel.name], resolve_var
            ):
                add(entry)
            continue
        if isinstance(sel, InlineFragment):
            if sel.type_condition is not None and sel.type_condition != meta_name:
                continue
            for entry in _merge_selections(
                sel.selection_set, desc, fragments, stack, resolve_var
            ):
                add(entry)
            continue
        # FieldNode
        if sel.name == "__typename":
            if sel.args:
                raise _invalid("'__typename' does not take arguments")
            if sel.selection_set is not None:
                raise _invalid("'__typename' must not have a selection set")
            add(("typename", sel.alias or sel.name, None, None, None))
            continue
        spec = field_table.get(sel.name)
        if spec is None:
            raise _invalid(
                f"unknown introspection field '{sel.name}' on type '{meta_name}'"
            )
        declared = _DECLARED_ARGS.get((meta_name, sel.name), frozenset())
        for arg_name in sel.args:
            if arg_name not in declared:
                raise _invalid(
                    f"unknown argument '{arg_name}' on introspection field "
                    f"'{sel.name}'"
                )
        shape, child_name, attr = spec
        key = sel.alias or sel.name
        if shape in ("leaf", "strlist"):
            if sel.selection_set is not None:
                raise _invalid(
                    f"introspection field '{sel.name}' must not have a selection set"
                )
            add(("field", key, attr, shape, None))
            continue
        if sel.selection_set is None:
            raise _invalid(
                f"introspection field '{sel.name}' requires a selection set"
            )
        child_desc = _placeholder_descriptor(child_name)
        child_entries = _merge_selections(
            sel.selection_set, child_desc, fragments, stack, resolve_var
        )
        if not child_entries:
            raise _invalid(
                f"introspection field '{sel.name}' requires a selection set"
            )
        add(("field", key, attr, shape, child_entries))

    if not out:
        raise _invalid("introspection selection set must not be empty")
    return out


def _placeholder_descriptor(meta_name: str) -> dict:
    """A descriptor standing in for a meta object type during validation."""
    if meta_name in ("__TypeKind", "__DirectiveLocation"):
        return {"kind": "ENUM", "name": meta_name}
    return {"kind": "OBJECT", "name": meta_name}


def compile_introspection_root(
    node: FieldNode,
    schema: Schema,
    fragments: Dict[str, Any],
    resolve_var: Callable[[Any], Any],
) -> dict:
    """Validate and compile one root ``__schema`` / ``__type`` field node."""
    key = node.alias or node.name
    if node.selection_set is None:
        raise _invalid(f"introspection field '{node.name}' requires a selection set")

    if node.name == "__schema":
        if node.args:
            raise _invalid("'__schema' does not take arguments")
        type_name: Optional[str] = None
    else:
        if "name" not in node.args:
            raise _invalid("'__type' is missing the required argument 'name'")
        for arg_name in node.args:
            if arg_name != "name":
                raise _invalid(
                    f"unknown argument '{arg_name}' on introspection field '__type'"
                )
        raw = node.args["name"]
        value = resolve_var(raw)
        if isinstance(value, bool) or not isinstance(value, str) or isinstance(
            value, EnumLiteral
        ) or value is None:
            raise _invalid("'__type' argument 'name' must be a String literal")
        type_name = value

    builder = _DescriptorBuilder(schema)
    if node.name == "__schema":
        root_desc = _placeholder_descriptor("__Schema")
    else:
        root_desc = builder.type_descriptor(type_name)
        if root_desc is None:
            # Unknown type name: resolve deterministically to null. The
            # selection is still validated for structural correctness.
            root_desc = _placeholder_descriptor("__Type")
    selections = _merge_selections(
        node.selection_set, root_desc, fragments, [], resolve_var
    )
    return {
        "introspection": node.name,
        "response_key": key,
        "type_name": type_name,
        "selections": selections,
    }


def resolve_introspection_root(root: dict, schema: Schema) -> Any:
    """Resolve a compiled introspection root against the schema."""
    builder = _DescriptorBuilder(schema)
    if root["introspection"] == "__schema":
        desc = builder.build_schema()
    else:
        desc = builder.type_descriptor(root["type_name"])
        if desc is None:
            return None
    return _resolve_selections(root["selections"], desc)


def _resolve_selections(entries: List[tuple], desc: dict) -> Dict[str, Any]:
    data: Dict[str, Any] = {}
    for entry in entries:
        kind = entry[0]
        key = entry[1]
        if kind == "typename":
            data[key] = desc["name"] if desc["name"] is not None else None
            # __typename on a wrapper returns the kind ("LIST"/"NON_NULL").
            if desc["name"] is None:
                data[key] = f"__{desc['kind'].title()}"
            continue
        _kind, _key, attr, shape, child_entries = entry
        value = desc.get(attr)
        if shape == "leaf":
            data[key] = value
        elif shape == "strlist":
            data[key] = list(value) if value is not None else None
        elif shape == "object":
            data[key] = (
                None if value is None else _resolve_selections(child_entries, value)
            )
        else:  # list of meta objects
            data[key] = (
                None
                if value is None
                else [_resolve_selections(child_entries, item) for item in value]
            )
    return data

