class QueryCompiler(Planner):
    """Compiles a query document into one executable entry per root field."""

    def __init__(self, schema: Schema, variables: Dict[str, Any],
                 bound_args_allowed: bool = False):
        super().__init__(schema, variables, bound_args_allowed)
        self.entity_keys: Dict[str, List[str]] = {}
        self.key_types: Dict[str, List[Any]] = {}

    def compile(
        self, query_text: str, source: str, operation_name: Optional[str]
    ) -> Tuple[Optional[str], List[dict]]:
        operations, self.fragments = parse_executable(query_text, source)
        op = self._select_operation(operations, operation_name)
        if op.op_type != "query":
            raise PlanError(
                "UnsupportedOperation",
                f"{op.op_type} operations are not supported by query-exec",
            )
        self.var_map = {}
        for name, type_ref, default, has_default in op.var_defs:
            if name in self.var_map:
                raise PlanError(
                    "VariablesError", f"variable '${name}' is declared more than once"
                )
            self.var_map[name] = (type_ref, default, has_default)

        root_type_name = self.schema.roots.get("query")
        root_type = self.schema.types.get(root_type_name) if root_type_name else None
        if root_type is None:
            raise PlanError(
                "MappingError",
                "schema does not define a root type for query operations",
            )

        selections = self._expand(op.selection_set, root_type.name, [])
        if not selections:
            raise PlanError("InvalidQuery", "query has an empty selection set")

        roots: List[dict] = []
        self.entity_keys = {}
        self.key_types = {}
        for node in selections:
            if node.name == "__typename":
                # __typename on the query root object names the root type.
                if node.args:
                    raise PlanError(
                        "InvalidQuery", "'__typename' does not take arguments"
                    )
                if node.selection_set is not None:
                    raise PlanError(
                        "InvalidQuery",
                        "'__typename' must not have a selection set",
                    )
                roots.append(
                    {"typename_root": node.alias or node.name,
                     "type_name": root_type.name}
                )
                continue
            if node.name in ("__schema", "__type"):
                # Introspection is always available (with or without complexity
                # control); it neither reads entities nor costs complexity.
                roots.append(
                    introspection.compile_introspection_root(
                        node,
                        self.schema,
                        self.fragments,
                        self._coerce_type_name_arg,
                        self._coerce_boolean_arg,
                    )
                )
                continue
            roots.append(self._compile_root(node, root_type))
        return op.name, roots

    # -- introspection argument coercion --------------------------------------

    def _coerce_type_name_arg(self, value: Any) -> str:
        """Coerce the ``__type(name:)`` argument to a String value.

        A variable must be declared with a String type (mismatch is a
        VariablesError); after resolution the value must be a non-null
        String literal rather than an enum/boolean/null literal.
        """
        if isinstance(value, Var):
            spec = self.var_map.get(value.name)
            if spec is not None and not _is_string_variable(spec[0]):
                raise PlanError(
                    "VariablesError",
                    f"variable '${value.name}' used for '__type' argument "
                    f"'name' must be a String",
                )
        value = self._resolve(value)
        if (
            value is None
            or isinstance(value, bool)
            or isinstance(value, EnumLiteral)
            or not isinstance(value, str)
        ):
            raise PlanError(
                "InvalidQuery", "'__type' argument 'name' must be a String literal"
            )
        return value

    def _coerce_boolean_arg(self, value: Any) -> bool:
        """Coerce an introspection Boolean argument (includeDeprecated).

        A variable must be declared with a Boolean type (mismatch is a
        VariablesError); the resolved value must then be a boolean literal.
