# -- selection tree -----------------------------------------------------------

def _compile_fields(
    self,
    info: TypeInfo,
    entity: Entity,
    selection_set,
    path: str,
) -> List[ExecNode]:
    selections = self._expand(selection_set, info.name, [])
    if not selections:
        raise PlanError("InvalidQuery", f"empty selection set at '{path}'")
    children: List[ExecNode] = []
    seen = set()
    for node in selections:
        key = node.alias or node.name
        node_path = f"{path}.{key}"
        if node.name == "__typename":
            if node.args:
                raise PlanError(
                    "InvalidQuery", "'__typename' does not take arguments"
                )
            if node.selection_set is not None:
                raise PlanError(
                    "InvalidQuery",
                    "'__typename' must not have a selection set",
                )
            if key not in seen:
                seen.add(key)
                children.append(
                    ExecNode(key, node.name, typename=info.name)
                )

